-- HD2-Addon: mods/cowboybingus/clickable_scrollbars
-- Generated by scripts/entry.py from src/bingus_runtime.lua, src/bingus_memory.lua, src/native.lua, src/memory.lua, src/locate.lua, src/model.lua, src/settings.lua, src/platform.lua, src/install.lua and src/clickable_scrollbars.lua; edit those instead.
local cs_files = {}
cs_files.bingus_runtime = function(...)
-- bingus_runtime.lua, version 1: the core of Bingus Shared Runtime.
-- Canonical copy: github.com/CowboyBingus/BingusSharedRuntime, runtime/bingus_runtime.lua.
--
-- Helldivers 2 runs the game and every Lua mod in one LuaJIT state, with one
-- global update chain. This file gives a mod the update guard every mod used
-- to write by hand, and the session table all runtime copies share. It uses no
-- FFI and no system function.
--
-- Loading: each runtime file is one chunk that returns a table and installs
-- nothing until the mod asks. A mod vendors byte-identical copies of the files
-- it needs and runs each once when it loads:
--   local runtime = <bingus_runtime.lua>              -- this file: shared(), guard()
--   local memory = <bingus_memory.lua>.new(runtime)   -- reads, page checks, module hashes, time()
--   <bingus_write.lua>.extend(memory)                 -- checked writes, added to memory
-- A mod that never touches memory vendors this file alone; one that only reads
-- vendors this file and bingus_memory.lua.
--
-- Copies of different versions can run in the same game. Their session state
-- lives in one global table, BingusRuntime = {hashes, statuses, versions,
-- hash_reads}, which every copy of every version shares.
--
-- runtime.shared([globals]) -> BingusRuntime, created or repaired.
-- runtime.guard(options) -> guard: the update and shutdown wrappers. The
-- previous update runs outside pcall, so its errors reach the game unchanged
-- (P1); the first failure survives shutdown as "stopped after: <reason>" (P2);
-- 8 errors stop the mod, counted per burst so rare transient errors never add
-- up (P3); a mod that can restore its state pauses after an error below it and
-- resumes when the updates below run cleanly again; every argument and return
-- value passes through; a status table per mod lands in BingusRuntime.statuses.
--
-- Per-frame cost of a guard: the mod's step under pcall, a few boolean tests
-- and stores and two integer counters around the previous update; no
-- allocation, closure or system call. Unmeasured in game.
local runtime = {VERSION = 1}

local type, pcall, error, tostring, rawget, rawset, ipairs = type, pcall, error, tostring, rawget, rawset, ipairs

-- Session state shared by every copy of every version ----------------------------

local SHARED = 'BingusRuntime'
local SHARED_TABLES = {'hashes', 'statuses', 'versions'}

-- Another copy, another version or another mod may have left the table
-- incomplete (even `BingusRuntime = {}`): missing or broken fields are filled in,
-- so one stray assignment cannot stop every mod on the runtime.
function runtime.shared(globals)
    globals = globals or _G
    local shared = rawget(globals, SHARED)
    if type(shared) ~= 'table' then
        shared = {}
        rawset(globals, SHARED, shared)
    end
    for _, field in ipairs(SHARED_TABLES) do
        if type(rawget(shared, field)) ~= 'table' then rawset(shared, field, {}) end
    end
    if type(rawget(shared, 'hash_reads')) ~= 'number' then rawset(shared, 'hash_reads', 0) end
    rawset(rawget(shared, 'versions'), runtime.VERSION, true)
    return shared
end

-- Update guard -----------------------------------------------------------------------

-- options:
--   name    key in BingusRuntime.statuses (required, one guard per name)
--   step    function(dt, ...) before the previous update, every frame while running
--   after   function() after the previous update returned, while running
--   stop    function(reason) once, when the guard stops or the game shuts down;
--           its errors are kept in status.stop_error, never raised
--   pause   function(reason), optional: an update below this mod raised; restore
--           the game state and reset the mod to a fresh start. With it the guard
--           pauses (no step, no after) and resumes once the updates below have
--           returned on `resume` frames in a row (default 60). Without it such an
--           error stops the guard. A pause that raises stops the guard.
--   log     function(line) for the guard's few lines (errors, pauses, resumes, stop)
--   errors  errors that stop the guard (default 8), counted separately for the
--           mod's own step and after and for the updates below it. A count starts
--           again after `clean` frames without such an error (default 3600, about a
--           minute at 60 FPS), so rare transient errors never add up to a stop.
--   env     the table holding update and shutdown (default _G)
-- guard.install() wraps env.update and env.shutdown and returns the guard.
-- guard.stop(reason) stops it from the mod (a refusal counts as the first failure).
-- guard.running() is true from install until a stop or shutdown.
-- guard.status: {name, version, state, installed, errors, lower_errors, pauses,
--   first_error, burst_error, first_failure, stop_error}; state is 'new', 'running',
--   'paused: <reason>', 'stopped: <reason>', then at shutdown 'stopped' or
--   'stopped after: <first failure>'.
function runtime.guard(options)
    local name = options.name
    if type(name) ~= 'string' or name == '' then error('guard name required', 0) end
    local shared = runtime.shared(options.env)
    if shared.statuses[name] and shared.statuses[name].installed then error('guard ' .. name .. ' already installed', 0) end
    local status = {name = name, version = runtime.VERSION, state = 'new', installed = false, errors = 0,
        lower_errors = 0, pauses = 0}
    shared.statuses[name] = status
    local step, after_step, stop_work, pause_work, log = options.step, options.after, options.stop, options.pause,
        options.log
    local limit, resume_after, clean_after = options.errors or 8, options.resume or 60, options.clean or 3600
    local previous_update, previous_shutdown
    local in_previous, stopped, paused, failed = false, false, false, false
    local clean_run, lower_run = 0, 0

    local function note(line)
        if log then pcall(log, line) end
    end

    local function halt(reason)
        if stopped then return end
        stopped, paused = true, false
        status.first_failure = status.first_failure or reason
        status.state = 'stopped: ' .. reason
        note(name .. ' stopped: ' .. reason)
        if stop_work then
            local ok, why = pcall(stop_work, reason)
            if not ok then status.stop_error = tostring(why) end
        end
    end

    -- The mod's own step or after raised: one log line per burst of errors.
    local function failed_step(problem)
        failed, clean_run = true, 0
        status.errors = status.errors + 1
        local text = tostring(problem)
        status.first_error = status.first_error or text
        if status.errors == 1 then
            status.burst_error = text
            note(name .. ' error: ' .. text)
        end
        if status.errors >= limit then halt('stopped after ' .. limit .. ' errors: ' .. status.burst_error) end
    end

    -- An update below this mod raised (seen on the next frame).
    local function failed_below()
        lower_run = 0
        status.lower_errors = status.lower_errors + 1
        if not pause_work then return halt('the previous update failed') end
        if status.lower_errors >= limit then
            return halt('stopped after ' .. limit .. ' failed updates below this mod')
        end
        if paused then return end
        paused = true
        status.pauses = status.pauses + 1
        status.state = 'paused: the previous update failed'
        note(name .. ' paused: the previous update failed')
        local ok, why = pcall(pause_work, 'the previous update failed')
        if not ok then halt('pause failed: ' .. tostring(why)) end
    end

    local function resume_when_clean()
        if paused and lower_run >= resume_after then
            paused = false
            status.state = 'running'
            note(name .. ' resumed after ' .. resume_after .. ' clean frames')
        end
    end

    -- Counts a frame without an own error, which also clears an old burst.
    local function count_clean()
        if failed then return end
        clean_run = clean_run + 1
        if clean_run == clean_after then status.errors = 0 end
    end

    local function finish(...)
        in_previous = false
        lower_run = lower_run + 1
        if lower_run == clean_after then status.lower_errors = 0 end
        if not stopped and not paused then
            if after_step then
                local ok, problem = pcall(after_step)
                if not ok then failed_step(problem) end
            end
            count_clean()
        end
        return ...
    end

    -- The previous update runs outside pcall: its errors (value and traceback)
    -- reach the game unchanged. One that raised leaves in_previous set, and the
    -- next frame pauses (or stops) this mod and keeps forwarding.
    local function update(...)
        failed = false
        if in_previous then
            in_previous = false
            if not stopped then failed_below() end
        end
        resume_when_clean()
        if step and not stopped and not paused then
            local ok, problem = pcall(step, ...)
            if not ok then failed_step(problem) end
        end
        in_previous = true
        return finish(previous_update(...))
    end

    local function shutdown(...)
        if in_previous then
            in_previous = false
            status.first_failure = status.first_failure or 'the previous update failed'
        end
        local failure = status.first_failure
        if not stopped then
            stopped = true
            if stop_work then
                local ok, why = pcall(stop_work, 'shutdown')
                if not ok then status.stop_error = tostring(why) end
            end
        end
        status.state = failure and ('stopped after: ' .. failure) or 'stopped'
        if previous_shutdown then return previous_shutdown(...) end
    end

    local guard = {status = status}

    function guard.install()
        local env = options.env or _G
        if status.installed then error('guard ' .. name .. ' already installed', 0) end
        previous_update = rawget(env, 'update')
        if type(previous_update) ~= 'function' then error('game update unavailable', 0) end
        previous_shutdown = rawget(env, 'shutdown')
        rawset(env, 'update', update)
        rawset(env, 'shutdown', shutdown)
        status.installed, status.state = true, 'running'
        return guard
    end

    function guard.stop(reason)
        halt(tostring(reason))
    end

    function guard.running()
        return status.installed and not stopped
    end

    return guard
end

return runtime
end
cs_files.bingus_memory = function(...)
-- bingus_memory.lua, version 1: the read side of Bingus Shared Runtime.
-- Canonical copy: github.com/CowboyBingus/BingusSharedRuntime, runtime/bingus_memory.lua.
--
-- Loading: the chunk returns {VERSION = 1, new = function(runtime)} and
-- installs nothing. A mod vendors a byte-identical copy next to
-- bingus_runtime.lua and runs each file once when it loads:
--   local runtime = <bingus_runtime.lua>
--   local memory = <bingus_memory.lua>.new(runtime)   -- the api below
--   <bingus_write.lua>.extend(memory)                 -- optional: checked writes
-- This file only reads memory, page information and module files; it never
-- changes memory or page protection. A mod whose build refuses sources that can
-- modify memory vendors bingus_runtime.lua and this file only.
--
-- Windows functions are declared under private, versioned FFI names
-- (bingus_memory1_*, each with an __asm__ label naming the real export), at
-- most once per version in the whole game. ffi.cdef keeps the first prototype
-- of a name for the whole game, so a plain name would bind to whatever another
-- mod declared first. Copies of other versions declare their own names.
--
-- memory.new(runtime) -> api. runtime is the table bingus_runtime.lua returns:
-- its shared table keeps module hashes for the session. Each api has its own
-- buffers and counters; every api of one copy shares the bound functions.
--   api.read(address, size)        the bytes as a string, or nil when they cannot
--                                  all be read; allocates only that string
--   api.read_into(address, size, buffer)  into a buffer the caller keeps: true or
--                                  false, no allocation
--   api.pointer(bytes [, offset])  the user-mode pointer stored little-endian at
--                                  bytes[offset+1 .. offset+8], as uint8_t *, or nil
--   api.address(pointer)           a pointer, number or integer cdata as a Lua number
--   api.distance(a, b)             api.address(a) - api.address(b)
--   api.writable_data(address, size)  true when [address, address + size) is
--                                  committed private read-write memory: never code,
--                                  read-only, guard or module image pages
--   api.queries                    page queries made so far (one per memory region)
--   api.time()                     seconds from the performance counter (a Lua number)
--   api.module([name])             a loaded module's base as uint8_t *, or nil;
--                                  no name: the executable
--   api.module_hash(module)        SHA-256 (uppercase hex) of the module's file, read
--                                  once per session for every mod (BingusRuntime.hashes)
--   api.verify_build(build)        build = {exe_sha256, game_sha256}: true, or false and why
--   api.windows                    {ffi, kernel32, bcrypt}: the bound functions under
--                                  their Windows names, for calls the api does not cover
-- Addresses are pointer cdata (read, read_into) or pointers, numbers and integer
-- cdata (address, distance, writable_data).
--
-- Cost per call: read and read_into one ReadProcessMemory (about 1-2 us in game);
-- writable_data one VirtualQuery per memory region in the range (about 0.29 ms
-- each in game), so check only on frames that act; time() one
-- QueryPerformanceCounter (unmeasured in game). read_into, address, distance,
-- writable_data and time allocate nothing, interpreted or compiled.
local memory = {VERSION = 1}

local type, error, pcall, tonumber, ipairs, pairs = type, error, pcall, tonumber, ipairs, pairs
local max, format, concat = math.max, string.format, table.concat

local HIGH = 4294967296
local MEM_COMMIT, MEM_PRIVATE, PAGE_READWRITE = 0x1000, 0x20000, 4

-- Windows functions ----------------------------------------------------------------

-- The region record is MEMORY_BASIC_INFORMATION with each 64-bit field read as
-- two 32-bit halves, and the cell turns a pointer into two halves through one
-- union (one base, so compiled code sees the store): neither allocates when read.
-- The region record is also this file's sentinel: once it exists, every
-- declaration below exists too.
local PREFIX = 'bingus_memory1_'
local SENTINEL = 'bingus_memory1_region'
local DECLARATIONS = [[
    typedef struct bingus_memory1_region {
        uint32_t base_low, base_high, allocation_base_low, allocation_base_high;
        uint32_t allocation_protection; uint16_t partition, reserved;
        uint32_t size_low, size_high, state, protection, type, padding;
    } bingus_memory1_region;
    typedef union bingus_memory1_cell {
        const void *pointer;
        struct { uint32_t low, high; };
    } bingus_memory1_cell;
    void *bingus_memory1_GetModuleHandleA(const char *name) __asm__("GetModuleHandleA");
    uint32_t bingus_memory1_GetModuleFileNameW(void *module, uint16_t *path, uint32_t capacity) __asm__("GetModuleFileNameW");
    void *bingus_memory1_GetCurrentProcess(void) __asm__("GetCurrentProcess");
    int bingus_memory1_ReadProcessMemory(void *process, const void *address, void *buffer, size_t size,
                                         size_t *done) __asm__("ReadProcessMemory");
    uint32_t bingus_memory1_VirtualQuery(uint64_t address, bingus_memory1_region *region, size_t size) __asm__("VirtualQuery");
    int bingus_memory1_QueryPerformanceCounter(uint32_t *count) __asm__("QueryPerformanceCounter");
    int bingus_memory1_QueryPerformanceFrequency(uint32_t *frequency) __asm__("QueryPerformanceFrequency");
    void *bingus_memory1_CreateFileW(const uint16_t *path, uint32_t access, uint32_t share, void *security,
                                     uint32_t disposition, uint32_t flags, void *template_file) __asm__("CreateFileW");
    int bingus_memory1_ReadFile(void *file, void *buffer, uint32_t size, uint32_t *done, void *overlapped) __asm__("ReadFile");
    int bingus_memory1_CloseHandle(void *handle) __asm__("CloseHandle");
    int32_t bingus_memory1_BCryptOpenAlgorithmProvider(void **algorithm, const uint16_t *name, const uint16_t *provider,
                                                       uint32_t flags) __asm__("BCryptOpenAlgorithmProvider");
    int32_t bingus_memory1_BCryptCloseAlgorithmProvider(void *algorithm, uint32_t flags) __asm__("BCryptCloseAlgorithmProvider");
    int32_t bingus_memory1_BCryptCreateHash(void *algorithm, void **hash, void *object, uint32_t object_size,
                                            const void *secret, uint32_t secret_size, uint32_t flags) __asm__("BCryptCreateHash");
    int32_t bingus_memory1_BCryptHashData(void *hash, const void *data, uint32_t size, uint32_t flags) __asm__("BCryptHashData");
    int32_t bingus_memory1_BCryptFinishHash(void *hash, void *digest, uint32_t size, uint32_t flags) __asm__("BCryptFinishHash");
    int32_t bingus_memory1_BCryptDestroyHash(void *hash) __asm__("BCryptDestroyHash");
]]
local FUNCTIONS = {
    kernel32 = {'GetModuleHandleA', 'GetModuleFileNameW', 'GetCurrentProcess', 'ReadProcessMemory', 'VirtualQuery',
                'QueryPerformanceCounter', 'QueryPerformanceFrequency', 'CreateFileW', 'ReadFile', 'CloseHandle'},
    bcrypt = {'BCryptOpenAlgorithmProvider', 'BCryptCloseAlgorithmProvider', 'BCryptCreateHash',
              'BCryptHashData', 'BCryptFinishHash', 'BCryptDestroyHash'},
}

local bound, ticks_per_second
-- {ffi, kernel32, bcrypt}, each library table holding the functions above under
-- their Windows names. Declared at most once per version in the whole game.
local function bind()
    if bound then return bound end
    local ffi = require('ffi')
    if not ffi.abi('64bit') then error('Windows x64 is required', 0) end
    if not pcall(ffi.typeof, SENTINEL) then ffi.cdef(DECLARATIONS) end
    local result = {ffi = ffi}
    for library, names in pairs(FUNCTIONS) do
        local loaded, functions = ffi.load(library), {}
        for _, name in ipairs(names) do functions[name] = loaded[PREFIX .. name] end
        result[library] = functions
    end
    local frequency = ffi.new('uint32_t[2]')
    if result.kernel32.QueryPerformanceFrequency(frequency) == 0 then error('performance counter unavailable', 0) end
    ticks_per_second = frequency[0] + frequency[1] * HIGH
    bound = result
    return bound
end

-- Module files ---------------------------------------------------------------------

-- SHA-256 (uppercase hex) of the file at path (a UTF-16 string buffer).
local function sha256(windows, path)
    local ffi, kernel, bcrypt = windows.ffi, windows.kernel32, windows.bcrypt
    local file = kernel.CreateFileW(path, 0x80000000, 7, nil, 3, 0x08000000, nil)
    if file == ffi.cast('void *', -1) then error('cannot read the module file', 0) end
    local algorithm, hash = ffi.new('void *[1]'), ffi.new('void *[1]')
    local ok, result = pcall(function()
        local id = ffi.new('uint16_t[7]', {83, 72, 65, 50, 53, 54, 0})  -- "SHA256"
        if bcrypt.BCryptOpenAlgorithmProvider(algorithm, id, nil, 0) ~= 0 then error('SHA-256 unavailable', 0) end
        if bcrypt.BCryptCreateHash(algorithm[0], hash, nil, 0, nil, 0, 0) ~= 0 then
            error('SHA-256 unavailable', 0)
        end
        local buffer, count = ffi.new('uint8_t[1048576]'), ffi.new('uint32_t[1]')
        while true do
            if kernel.ReadFile(file, buffer, 1048576, count, nil) == 0 then error('module file read failed', 0) end
            if count[0] == 0 then break end
            if bcrypt.BCryptHashData(hash[0], buffer, count[0], 0) ~= 0 then error('SHA-256 failed', 0) end
        end
        local digest, hex = ffi.new('uint8_t[32]'), {}
        if bcrypt.BCryptFinishHash(hash[0], digest, 32, 0) ~= 0 then error('SHA-256 failed', 0) end
        for i = 0, 31 do hex[i + 1] = format('%02X', digest[i]) end
        return concat(hex)
    end)
    if hash[0] ~= nil then bcrypt.BCryptDestroyHash(hash[0]) end
    if algorithm[0] ~= nil then bcrypt.BCryptCloseAlgorithmProvider(algorithm[0], 0) end
    kernel.CloseHandle(file)
    if not ok then error(result, 0) end
    return result
end

-- The SHA-256 of a loaded module's file, read once per session for every mod:
-- kept in the shared table by file path.
local function module_hash(runtime, windows, module)
    local ffi = windows.ffi
    local path = ffi.new('uint16_t[32768]')
    local length = windows.kernel32.GetModuleFileNameW(module, path, 32768)
    if length == 0 or length >= 32768 then error('module file name unavailable', 0) end
    local shared = runtime.shared()
    local key = 'sha256:' .. ffi.string(path, length * 2)
    local cached = shared.hashes[key]
    if cached then return cached end
    local hex = sha256(windows, path)
    shared.hash_reads = shared.hash_reads + 1
    shared.hashes[key] = hex
    return hex
end

-- The api --------------------------------------------------------------------------

function memory.new(runtime)
    if type(runtime) ~= 'table' or type(runtime.shared) ~= 'function' then
        error('bingus_memory.lua: new(runtime) needs the table bingus_runtime.lua returns', 2)
    end
    runtime.shared()
    local windows = bind()
    local ffi, kernel = windows.ffi, windows.kernel32
    local read_memory, query, query_counter = kernel.ReadProcessMemory, kernel.VirtualQuery,
        kernel.QueryPerformanceCounter
    local process = kernel.GetCurrentProcess()
    -- ReadProcessMemory reports its count as a 64-bit size: it is read back as two
    -- 32-bit words, because reading the 64-bit value boxes a new cdata in
    -- interpreted code. Only the call writes this buffer.
    local done = ffi.new('size_t[1]')
    local done32 = ffi.cast('uint32_t *', done)
    local region, region_size = ffi.new(SENTINEL), ffi.sizeof(SENTINEL)
    local cell, counter = ffi.new('bingus_memory1_cell'), ffi.new('uint32_t[2]')
    local scratch_size = 256
    local scratch = ffi.new('uint8_t[?]', scratch_size)
    local ticks = ticks_per_second
    local api = {queries = 0, windows = windows}

    -- A pointer, number or integer cdata as a number, without allocating: a
    -- pointer passes through the cell. Exact below 2^53 (user-mode addresses
    -- end at 2^47).
    local function address_of(address)
        if type(address) == 'number' then return address end
        if type(address) == 'cdata' then
            local integer = tonumber(address)
            if integer then return integer end
        end
        cell.pointer = address
        return cell.low + cell.high * HIGH
    end

    function api.module(name)
        local handle = kernel.GetModuleHandleA(name)
        if handle == nil then return nil end
        return ffi.cast('uint8_t *', handle)
    end

    -- The bytes at address as a string, or nil when they cannot all be read.
    -- Allocates only the returned string.
    function api.read(address, size)
        if size > scratch_size then
            scratch_size = max(size, scratch_size * 2)
            scratch = ffi.new('uint8_t[?]', scratch_size)
        end
        if read_memory(process, address, scratch, size, done) == 0 or done32[0] ~= size then
            return nil
        end
        return ffi.string(scratch, size)
    end

    -- Into a buffer the caller keeps: no allocation at all.
    function api.read_into(address, size, buffer)
        return read_memory(process, address, buffer, size, done) ~= 0 and done32[0] == size
    end

    -- The user-mode pointer stored little-endian at bytes[offset+1 .. offset+8].
    function api.pointer(bytes, offset)
        offset = offset or 0
        if type(bytes) ~= 'string' or offset < 0 or offset + 8 > #bytes then return nil end
        local b1, b2, b3, b4, b5, b6, b7, b8 = bytes:byte(offset + 1, offset + 8)
        if b7 ~= 0 or b8 ~= 0 then return nil end
        local value = b1 + b2 * 256 + b3 * 65536 + b4 * 16777216 + (b5 + b6 * 256) * HIGH
        if value < 0x10000 or value >= 0x800000000000 then return nil end
        return ffi.cast('uint8_t *', value)
    end

    api.address = address_of

    function api.distance(first, second)
        return address_of(first) - address_of(second)
    end

    -- True when [address, address + size) is committed private read-write memory:
    -- never code, read-only, guard or module image pages. One VirtualQuery per
    -- region, each answered in the region record (no allocation).
    function api.writable_data(address, size)
        if type(size) ~= 'number' or size <= 0 then return false end
        local cursor = address_of(address)
        local finish = cursor + size
        while cursor < finish do
            api.queries = api.queries + 1
            if query(cursor, region, region_size) ~= region_size then return false end
            if region.state ~= MEM_COMMIT or region.type ~= MEM_PRIVATE or region.protection ~= PAGE_READWRITE then
                return false
            end
            local region_end = region.base_low + region.base_high * HIGH + region.size_low + region.size_high * HIGH
            if region_end <= cursor then return false end
            cursor = region_end
        end
        return true
    end

    -- Seconds since an arbitrary start (boot), from the performance counter read
    -- as two 32-bit halves into a reused buffer; the frequency is read once.
    function api.time()
        query_counter(counter)
        return (counter[0] + counter[1] * HIGH) / ticks
    end

    function api.module_hash(module)
        return module_hash(runtime, windows, module)
    end

    -- build: {exe_sha256, game_sha256}. true, or false and why.
    function api.verify_build(build)
        local exe, game = api.module(nil), api.module('game.dll')
        if not exe or not game then return false, 'game modules unavailable' end
        if api.module_hash(exe) ~= build.exe_sha256 or api.module_hash(game) ~= build.game_sha256 then
            return false, 'unsupported game build'
        end
        return true
    end

    return api
end

return memory
end
cs_files.native = function(...)
-- The UI bridge, the native grid's layout in this build, the game's scroll and
-- input routines, and the native writes that drive them.
local module, cs = ...

-- The engine's UI is reachable from Lua: equipment scrollbars are the game's own
-- ScrollBar objects, and driving one is a data write rather than synthesised input.
-- Anchors are the ones the shipped Armory mods use (game+0x347cd90 is the UI root,
-- game+0x3326e68 the dispatch table); nothing is written until the object is found.
function module.ui_bridge(create_api)
    if type(create_api) ~= 'function' then return nil, 'no api factory' end
    local ok, api = pcall(create_api)
    if not ok or type(api) ~= 'table' then return nil, 'api unavailable' end
    local ok2, result = pcall(function()
        if api.assert_thread then api.assert_thread() end
        local game = api.module('game.dll')
        if not game then return nil, 'game.dll unavailable' end
        local bridge = {api = api, game = game}
        bridge.ui = api.pointer(api.read(game + 0x347cd90, 8))
        bridge.dispatch = api.pointer(api.read(game + 0x3326e68, 8))
        return bridge
    end)
    if not ok2 then return nil, tostring(result) end
    if type(result) ~= 'table' then return nil, 'anchors unreadable' end
    return result
end

-- ------------------------------------------------------------- native grid

-- Armory and loadout equipment use a ScrollBar and a virtualized grid; Career
-- scrolls a widget container and derives its thumb during the frame update.
-- Both are driven directly, without synthesised input. These grid fields were
-- read from the shipped build (game.dll CC75948D...) and are bounds-checked;
-- nothing is written unless the whole chain resolves.
local GRID = {
    offset = 523752,        -- controller + ...            -> the item grid
    rows = 597772,          -- int, visible row slots
    row_heights = 597784,   -- float px, one per laid-out row
    row_items = 598808,     -- int, items in that row
    selected = 600308,      -- int, the highlighted item
    content = 600424,       -- float px, laid-out content height
    scroll = 600416,        -- float px, how far the list is scrolled
    span = 0x8C0,           -- float px, content - viewport (the scrollable span)
    value = 0x8C8,          -- float 0..1, the scrollbar's own value
    first = 622656,         -- int, first visible item
    last = 622660,          -- int, last visible item
    anchor = 602096,        -- int, the centre index the solver last published
    items = 600452,         -- int, items in the open category
    columns = 47540,        -- int, first visible row's actual item count
    kind = 602052,          -- int, category/layout type
    row_base = 2816,        -- first row slot
    row_stride = 44752,
    max_rows = 16,
    max_columns = 8,
    max_items = 100000,
    max_pixels = 1000000,
}

-- The largest block native_state reads at once (the grid's row-table block).
local BLOCK_BYTES = 4352
local CAREER = {offset = 318472, list = 2488, track = 195256, thumb = 195808,
                thumb_height = 196148, enabled = 196089, padding = 4}
local LOADOUT_GRID_OFFSET = 864032
-- Both the settings page and Bindings own inline virtual lists of the same
-- widget type. Page offsets were measured in Steam build 25480438.
local OPTIONS_LIST = {bar = 816, thumb = 1432,
                      scroll = 552, span = 2784, value = 2792}
local OPTIONS_PAGES = {
    [1] = {menu = 200, list = 4189984, route = 'settings'},
    [26] = {menu = 208, list = 338344, route = 'bindings'},
}
local GRID_SOLVER, SCROLL_SET, POSITION_SET, ANIMATION_STOP =
    0x18d2b60, 0x1794530, 0x14476a0, 0x1439d40
local INPUT_CONSUME, INPUT_STATE, UI_SELECT = 0x12fde90, 0x347cf18, 0xA00000000
module.native_signatures = {
    {GRID_SOLVER, '488bc45355565741544155415641574881ecf800000083b9'},
    {SCROLL_SET, '0f57d20f2fd1770cf30f10153028c300f30f5dd1f30f1081'},
    {POSITION_SET, '48895c241848896c24204889542410565741574883ec20f3'},
    {ANIMATION_STOP, '40534883ec40488b05c32220014833c448894424300fb601'},
    {INPUT_CONSUME, '40534883ec204c8bd14c8bca488bcae8dc7c28ff'},
}

local function native_key(pointer)
    if type(pointer) == 'cdata' then
        pointer = tonumber(require('ffi').cast('uintptr_t', pointer))
    end
    -- The game's tostring hides cdata values as "[cdata (deleted)]".
    return string.format('%.0f', pointer)
end

-- The native layer carries the two small predicates it needs rather than
-- sharing clamp: its functions stay in the interpreter (keep_interpreted), and
-- a shared clamp would keep the per-frame steps' calls of it there too.
-- Addresses are plain numbers in the offline model and FFI pointers in game.
local function native_clamp(value, low, high)
    if value < low then return low end
    if value > high then return high end
    return value
end

local function native_address(value)
    return type(value) == 'number' or type(value) == 'cdata'
end

-- Detector fallback geometry. Native hit testing uses widget transforms below;
-- if a measured thumb is used, preserve the game's actual thumb ratio (which
-- includes padding and need not equal viewport/content).
function module.native_track(model, thumb_top, thumb_length)
    if type(model) ~= 'table' or type(thumb_top) ~= 'number' or type(thumb_length) ~= 'number' then
        return nil
    end
    if thumb_length < 6 or not model.content or not model.viewport or model.viewport <= 0 then
        return nil
    end
    local ratio = model.thumb_ratio or model.viewport / model.content
    if ratio ~= ratio or ratio <= 0 or ratio >= 1 then return nil end
    local length = thumb_length / ratio
    if length ~= length or length <= thumb_length or length > GRID.max_pixels then return nil end
    return {top = thumb_top - model.value * (length - thumb_length), length = length,
            thumb = thumb_length, span = length - thumb_length}
end

-- Where a track press aims: the thumb's centre goes under the pointer, which is
-- what a native page click does.
function module.native_value(model, cursor_y, track)
    if type(model) ~= 'table' or type(track) ~= 'table' or not track.span or track.span <= 0 then
        return nil
    end
    local value = (cursor_y - track.top - track.thumb / 2) / track.span
    if value ~= value then return nil end
    return native_clamp(value, 0, 1)
end

-- Where a held drag aims: the bar keeps the grab point under the pointer, so the
-- value moves by exactly the distance the pointer moved.
function module.native_value_at_grab(model, track, press_y, cursor_y)
    if type(model) ~= 'table' or type(track) ~= 'table' or not track.span or track.span <= 0 then
        return nil
    end
    if type(model.value) ~= 'number' or type(press_y) ~= 'number' then return nil end
    local value = model.value + (cursor_y - press_y) / track.span
    if value ~= value then return nil end
    return native_clamp(value, 0, 1)
end

-- The write itself: the value plus the pixel offset the game derives from it.
-- Both are written so the model is consistent whichever one the engine reads
-- first, and both are bounded before they leave.
function module.native_set(memory, grid, model, value)
    if type(memory) ~= 'table' or not native_address(grid) or type(model) ~= 'table' then
        return nil, 'not ready'
    end
    if type(value) ~= 'number' or value ~= value then return nil, 'invalid value' end
    if type(model.span) ~= 'number' or model.span <= 0 or model.span > GRID.max_pixels
        or model.span ~= model.span then return nil, 'invalid span' end
    value = native_clamp(value, 0, 1)
    if not memory.write_f32 or not memory.write_f32(grid + GRID.value, value) then
        return nil, 'write refused'
    end
    if not memory.write_f32(grid + GRID.scroll, value * model.span) then
        memory.write_f32(grid + GRID.value, model.value)
        return nil, 'scroll write refused'
    end
    return value
end

-- Function pointer and vector types, declared once per process by name. A type
-- string such as 'void (*)(void *)' creates new C types every time it is cast,
-- and the type table every mod shares never frees them (65536 entries). The
-- union packs the two-float vector through one base, so compiled code cannot
-- read it back stale.
local NATIVE_TYPES = [[
    typedef void (*hd2cs_native_ptr)(void *);
    typedef void (*hd2cs_native_ptr_float)(void *, float);
    typedef void (*hd2cs_native_ptr_u64)(void *, uint64_t);
    typedef void (*hd2cs_native_ptr_u64_float)(void *, uint64_t, float);
    typedef union { float f[2]; uint64_t u; } hd2cs_vec2_bits;
]]
local native_cache = {}

-- Use the same setters and layout sequence as the game's scroll handlers.
-- A raw value write skips the thumb update; an active animation can overwrite
-- the requested position. Native calls execute from the loader's frame callback.
-- The functions are cast once per game module base and reused for the session.
function module.native_calls(bridge)
    local ffi = require('ffi')
    local game = bridge.game
    -- api.module returns a new pointer object each time; key the cache by address.
    local key = type(game) == 'number' and game or tonumber(ffi.cast('uintptr_t', game))
    local cached = native_cache[key]
    if cached then return cached end
    if not pcall(ffi.typeof, 'hd2cs_vec2_bits') then ffi.cdef(NATIVE_TYPES) end
    local ptr, ptr_float = ffi.typeof('hd2cs_native_ptr'), ffi.typeof('hd2cs_native_ptr_float')
    local ptr_u64, ptr_u64_float = ffi.typeof('hd2cs_native_ptr_u64'), ffi.typeof('hd2cs_native_ptr_u64_float')
    local stop = ffi.cast(ptr, game + ANIMATION_STOP)
    local scroll = ffi.cast(ptr_float, game + SCROLL_SET)
    local position = ffi.cast(ptr_u64, game + POSITION_SET)
    local solve = ffi.cast(ptr, game + GRID_SOLVER)
    local consume = ffi.cast(ptr_u64_float, game + INPUT_CONSUME)
    local bytes = ffi.typeof('uint8_t *')
    local xy = ffi.new('hd2cs_vec2_bits')
    local calls = {}
    -- The last grid's animation flag and stop target, so that a drag frame
    -- computes no pointer.
    local stop_grid, stop_flag, stop_target
    function calls.stop(grid)
        if grid ~= stop_grid then
            stop_grid, stop_flag, stop_target = grid, ffi.cast(bytes, grid + 600322), grid + 600320
        end
        if stop_flag[0] ~= 0 then stop(stop_target) end
    end
    function calls.scroll(bar, value)
        scroll(bar, value)
    end
    function calls.position(widget, x, y)
        -- The engine passes its two-float vector in the second integer register.
        -- An FFI struct argument is not interchangeable with that ABI.
        xy.f[0], xy.f[1] = x, y
        position(widget, xy.u)
    end
    function calls.solve(grid)
        solve(grid)
    end
    function calls.consume(input, action)
        -- Match the game's buttons: -1 consumes this action until release.
        -- Action ids are below 2^53, so the number converts to uint64_t exactly.
        consume(input, action, -1)
    end
    native_cache[key] = calls
    return calls
end

-- The game routines, looked up once per resolved owner.
local function owner_calls(bridge)
    local calls = bridge.calls
    if not calls then
        calls = module.native_calls(bridge)
        bridge.calls = calls
    end
    return calls
end

-- The addresses a route writes, computed once per resolved owner so that a drag
-- frame computes no pointer.
local function write_targets(bridge)
    local targets = bridge.targets
    if targets then return targets end
    local route = bridge.route
    if route == 'career' then
        targets = {list = bridge.panel + CAREER.list}
    elseif route == 'bindings' or route == 'settings' then
        targets = {content = bridge.grid + 544}
    else
        targets = {bar = bridge.grid + 272, scroll = bridge.grid + GRID.scroll}
    end
    bridge.targets = targets
    return targets
end

-- Runs under pcall in native_apply (a named function, so no closure per drag frame).
local function apply_native(bridge, model, value, calls)
    calls = calls or owner_calls(bridge)
    local targets = write_targets(bridge)
    if bridge.route == 'career' then
        -- Career scrolls a container. Its frame update derives the thumb
        -- from (container.y + padding) / (content - viewport).
        calls.position(targets.list, model.list_x, value * model.span - CAREER.padding)
    elseif bridge.route == 'bindings' or bridge.route == 'settings' then
        -- The game's list input handler updates both objects in this order:
        -- the scrollbar value, then the content container's vertical
        -- position. Updating only the bar moves the thumb but not rows.
        calls.scroll(bridge.bar, value)
        calls.position(targets.content, 0, value * model.span)
    else
        -- Follow the game's wheel handler: stop an existing animation,
        -- update the scrollbar (including its rendered thumb), then layout.
        -- Writing value first would make the native setter skip its work.
        calls.stop(bridge.grid)
        calls.scroll(targets.bar, value)
        if not bridge.memory.write_f32(targets.scroll, value * model.span) then
            calls.scroll(targets.bar, model.value)
            error('scroll write refused', 0)
        end
        calls.solve(bridge.grid)
    end
end

function module.native_apply(bridge, model, value, calls)
    if type(bridge) ~= 'table' or not bridge.memory or not model
        or type(value) ~= 'number' or value ~= value
        or not model.span or model.span <= 0 or model.span ~= model.span
        or model.span > GRID.max_pixels then return nil, 'invalid native target' end
    value = native_clamp(value, 0, 1)
    local ok, err = pcall(apply_native, bridge, model, value, calls)
    if not ok then return nil, tostring(err) end
    return value
end

-- Settings rows and tabs both read UI_SELECT, including its held value. The
-- list's 0.5-second timer is not a capture gate: its update adds dt before row
-- input, and tabs bypass it entirely. Consume the selection through the same
-- engine routine used by buttons; it clears all frame copies and held values.
-- The OS button/cursor remain untouched and continue driving our scroll model.
-- The input owner is read every frame of a settings hold (a previous menu owner
-- may be gone), but decoded again only when its pointer's bytes change.
local function input_owner(bridge)
    local api, slot = bridge.api, bridge.input_slot
    if not slot then
        slot = bridge.game + INPUT_STATE
        bridge.input_slot = slot
    end
    local bytes = api.read(slot, 8)
    if bytes ~= bridge.input_bytes then
        bridge.input_bytes, bridge.input = bytes, api.pointer(bytes)
    end
    return bridge.input
end

local function consume_select(bridge, calls)
    local input = input_owner(bridge)
    if not input then return false end
    calls = calls or owner_calls(bridge)
    return calls.consume(input, UI_SELECT) ~= false
end

function module.native_settings_input(bridge, calls)
    if not bridge or bridge.route ~= 'settings' or not bridge.api or not bridge.game then
        return nil, 'not a settings list'
    end
    local ok, result = pcall(consume_select, bridge, calls)
    if not ok or not result then return nil, 'settings input consume failed' end
    return true
end

function module.native_moved(before, after)
    if type(before) ~= 'table' or type(after) ~= 'table' then return false end
    if before.kind == 'bindings' or before.kind == 'settings' then
        -- The options route never writes the content offset directly; this is
        -- evidence that the game's container position setter answered.
        return after.kind == before.kind and before.scroll and after.scroll
            and math.abs(before.scroll - after.scroll) > 0.1 or false
    end
    -- Only the fields the game itself derives count: the value and the pixel
    -- offset are what this addon writes, so comparing them with themselves would
    -- read a write back as a success.
    if before.first and after.first and after.first ~= before.first then return true end
    if before.last and after.last and after.last ~= before.last then return true end
    if before.anchor and after.anchor and after.anchor ~= before.anchor then return true end
    if before.rendered_thumb and after.rendered_thumb
        and math.abs(before.rendered_thumb - after.rendered_thumb) > 0.1 then return true end
    return false
end

-- For the files that read the same objects.
cs.GRID, cs.BLOCK_BYTES, cs.CAREER, cs.LOADOUT_GRID_OFFSET = GRID, BLOCK_BYTES, CAREER, LOADOUT_GRID_OFFSET
cs.OPTIONS_LIST, cs.OPTIONS_PAGES = OPTIONS_LIST, OPTIONS_PAGES
cs.native_key, cs.native_clamp, cs.native_address = native_key, native_clamp, native_address

cs.keep_interpreted({module.native_calls, module.native_apply, apply_native, owner_calls, write_targets,
    module.native_settings_input, consume_select, input_owner, module.native_moved, module.native_value_at_grab,
    module.native_value, module.native_track, module.native_set, native_clamp, native_address, native_key})
end
cs_files.memory = function(...)
-- Memory views over the game's objects, and the reader the addon ships with.
local module, cs = ...
local GRID, BLOCK_BYTES = cs.GRID, cs.BLOCK_BYTES

-- One block buffer serves every memory view: native_state decodes a block
-- before it reads the next one and is never re-entered.
local block_buffer
local function shared_block(ffi)
    if not block_buffer then
        local bytes = ffi.new('uint8_t[?]', BLOCK_BYTES)
        block_buffer = {bytes = bytes, u32 = ffi.cast('uint32_t *', bytes), f32 = ffi.cast('float *', bytes)}
    end
    return block_buffer
end

-- A memory view is the only thing the native layer needs, so the code that runs
-- in game is the code the offline model exercises. With a reader that fills
-- caller buffers (read_into: the shipped reader) a field read allocates nothing;
-- other readers return strings.
function module.native_memory(api)
    if type(api) ~= 'table' or type(api.read) ~= 'function' then return nil, 'no reader' end
    local ok, ffi = pcall(require, 'ffi')
    if not ok then return nil, 'ffi unavailable' end
    local word, real = ffi.new('uint32_t[1]'), ffi.new('float[1]')
    local memory = {api = api, float = real, word = word}
    local function read4(address, buffer)
        if api.read_into then return api.read_into(address, buffer, 4) end
        local bytes = api.read(address, 4)
        if type(bytes) ~= 'string' or #bytes < 4 then return false end
        ffi.copy(buffer, bytes, 4)
        return true
    end
    function memory.read_u32(address)
        if not read4(address, word) then return nil end
        return tonumber(word[0])
    end
    function memory.read_f32(address)
        if not read4(address, real) then return nil end
        return tonumber(real[0])
    end
    -- native_state's block reads: one read of up to BLOCK_BYTES into the shared
    -- block, decoded through its two typed views (only the reader writes it).
    if api.read_into then
        local block = shared_block(ffi)
        memory.block_u32, memory.block_f32 = block.u32, block.f32
        function memory.read_block(address, size)
            return size <= BLOCK_BYTES and api.read_into(address, block.bytes, size) == true
        end
    end
    -- A direct store (the build keeps the process-memory write API loader-only). pcall
    -- turns a malformed address into false; it cannot catch an access violation, so
    -- callers only pass addresses of objects re-validated in the same frame.
    local floats = ffi.typeof('float *')
    local function store_f32(address, value)
        ffi.cast(floats, address)[0] = value -- lint-ok: R3 the direct store described above
    end
    function memory.write_f32(address, value)
        if type(value) ~= 'number' or value ~= value or math.abs(value) > GRID.max_pixels then return false end
        return (pcall(store_f32, address, value))
    end
    return memory
end

-- The reader the addon ships with: a module handle plus a bounded read of this
-- process. Its Windows functions have private names (__asm__ labels): LuaJIT
-- keeps the first prototype declared for a name in the whole process, so
-- another mod's declaration of the real names cannot change these calls.
function module.native_reader()
    local ok, ffi = pcall(require, 'ffi')
    if not ok or not ffi.abi('64bit') then return nil, 'ffi unavailable' end
    pcall(ffi.cdef, [[
        void *hd2cs_GetModuleHandleA(const char *name) __asm__("GetModuleHandleA");
        void *hd2cs_GetCurrentProcess(void) __asm__("GetCurrentProcess");
        int hd2cs_ReadProcessMemory(void *process, const void *address, void *buffer, size_t size,
                                    size_t *read) __asm__("ReadProcessMemory");
    ]])
    local kernel32 = ffi.load('kernel32')
    local process = kernel32.hd2cs_GetCurrentProcess()
    -- ReadProcessMemory reports the bytes it copied through a SIZE_T, kept here
    -- as two words read as numbers (a size_t element is boxed on every read).
    local copied_words = ffi.new('uint32_t[2]')
    local copied = ffi.cast('size_t *', copied_words)
    local scratch, scratch_size = nil, 0
    local function valid_size(size)
        return type(size) == 'number' and size >= 1 and size <= 32768 and size % 1 == 0
    end
    -- True only when all size bytes at address were copied into buffer.
    local function copy(address, buffer, size)
        if kernel32.hd2cs_ReadProcessMemory(process, address, buffer, size, copied) == 0 then return false end
        return copied_words[0] == size and copied_words[1] == 0
    end
    local api = {}
    -- While api.tape is set (native_resolve), every read is appended to it as
    -- address, size and the bytes read (false when unreadable).
    local function record(address, size, bytes)
        local tape = api.tape
        local slot = tape.n * 3
        tape[slot + 1], tape[slot + 2], tape[slot + 3] = address, size, bytes or false
        tape.n = tape.n + 1
    end
    function api.module(name)
        local handle = kernel32.hd2cs_GetModuleHandleA(name)
        if handle == nil then return nil end
        return ffi.cast('uint8_t *', handle)
    end
    -- Fills a caller's buffer: no allocation.
    function api.read_into(address, buffer, size)
        local read = valid_size(size) and copy(address, buffer, size)
        if api.tape then record(address, size, read and ffi.string(buffer, size)) end
        return read
    end
    -- One scratch buffer serves every string read; bytes that did not change
    -- come back as the same interned string, so a repeated read allocates nothing.
    function api.read(address, size)
        local bytes = nil
        if valid_size(size) then
            if size > scratch_size then scratch, scratch_size = ffi.new('uint8_t[?]', size), size end
            if copy(address, scratch, size) then bytes = ffi.string(scratch, size) end
        end
        if api.tape then record(address, size, bytes) end
        return bytes
    end
    function api.pointer(bytes, offset)
        offset = offset or 0
        if type(bytes) ~= 'string' or offset < 0 or offset + 8 > #bytes then return nil end
        local value = ffi.new('uintptr_t[1]')
        ffi.copy(value, bytes:sub(offset + 1, offset + 8), 8)
        if value[0] < 0x10000 or value[0] >= 0x800000000000 then return nil end
        return ffi.cast('uint8_t *', value[0])
    end
    return api
end

function module.native_api()
    local api, reason = module.native_reader()
    if not api then return nil, reason end
    -- Refuse all native scrolling if any called routine differs from this build.
    local game = api.module('game.dll')
    for _, entry in ipairs(module.native_signatures) do
        local bytes = entry[2]:gsub('..', function(hex) return string.char(tonumber(hex, 16)) end)
        if not game or api.read(game + entry[1], #bytes) ~= bytes then
            return nil, 'unsupported native scroll routine'
        end
    end
    return api
end

cs.keep_interpreted({module.native_reader, module.native_memory})
end
cs_files.locate = function(...)
-- Which scrollbar is visible and who owns it, and whether that still holds.
local module, cs = ...
local GRID, CAREER, LOADOUT_GRID_OFFSET = cs.GRID, cs.CAREER, cs.LOADOUT_GRID_OFFSET
local OPTIONS_LIST, OPTIONS_PAGES, native_key = cs.OPTIONS_LIST, cs.OPTIONS_PAGES, cs.native_key

-- Resolve the live equipment grid from its screen's registered controller.
-- Ship Armory uses kind 224; the mission loadout picker uses kind 229 and embeds
-- the same grid at a different controller offset in build 25480438.
function module.native_locate(api, memory) -- lint-ok: R10 moved unchanged from the single file; existing debt, not new
    if type(api) ~= 'table' then return nil, 'no reader' end
    memory = memory or module.native_memory(api)
    if not memory then return nil, 'no memory view' end
    local game = api.module('game.dll')
    if not game then return nil, 'game.dll unavailable' end
    local dispatch = api.pointer(api.read(game + 0x3326e68, 8))
    if not dispatch then return nil, 'dispatch table unavailable' end
    local count = memory.read_u32(dispatch + 5740)
    if not count or count < 1 or count > 64 then return nil, 'dispatch bounds changed' end
    -- Snapshot the bounded registry once instead of a system call per row.
    local rows = api.read(dispatch + 5744, count * 16)
    if type(rows) ~= 'string' or #rows ~= count * 16 then return nil, 'dispatch rows unreadable' end

    local has_armory, has_loadout = false, false
    for index = 0, count - 1 do
        local kind = rows:byte(index * 16 + 9)
            + rows:byte(index * 16 + 10) * 256
            + rows:byte(index * 16 + 11) * 65536
            + rows:byte(index * 16 + 12) * 16777216
        if kind == 224 then has_armory = true
        elseif kind == 229 then has_loadout = true end
    end
    local active_kind
    if has_loadout then
        -- The loadout controller can remain registered while a different UI
        -- state is on top. Use the screen stack when readable; captured tests
        -- without that optional anchor still use visible-widget validation.
        local ok, value = pcall(function()
            local stack_owner = api.pointer(api.read(game + 0x347ce28, 8))
            if not stack_owner then return nil end
            local stack = api.read(stack_owner + 0x429c, 24)
            if type(stack) ~= 'string' or #stack < 24 then return nil end
            local function word(offset)
                local a, b, c, d = stack:byte(offset + 1, offset + 4)
                if not d then return nil end
                return a + b * 256 + c * 65536 + d * 16777216
            end
            local depth = word(20)
            if not depth or depth < 1 or depth > 5 then return false end
            local top = word((depth - 1) * 4)
            if top == 5 then return 224 end
            if top == 14 then return 229 end
            return false
        end)
        if ok then active_kind = value end
        if active_kind == false then return nil, 'unsupported UI screen' end
    end

    for index = 0, count - 1 do
        local offset = index * 16
        local kind = rows:byte(offset + 9)
            + rows:byte(offset + 10) * 256
            + rows:byte(offset + 11) * 65536
            + rows:byte(offset + 12) * 16777216
        if (kind == 224 or kind == 229) and (not active_kind or kind == active_kind) then
            local controller = api.pointer(rows, offset)
            if not controller then return nil, 'equipment controller unavailable' end
            local grid_offset = kind == 224 and GRID.offset or LOADOUT_GRID_OFFSET
            local bridge = {api = api, memory = memory, game = game, controller = controller,
                            kind = kind, grid = controller + grid_offset,
                            panel = kind == 224 and controller + CAREER.offset or nil}
            -- Resolved alpha includes parent visibility. The equipment grid
            -- remains allocated behind Career and must never own its gestures.
            if bridge.panel and (memory.read_f32(bridge.panel + CAREER.track + 84) or 0) > 0.95 then
                bridge.route = 'career'
                bridge.bar, bridge.thumb = bridge.panel + CAREER.track, bridge.panel + CAREER.thumb
            elseif (memory.read_f32(bridge.grid + 272 + 84) or 0) > 0.95 then
                bridge.route = 'grid'
                bridge.bar, bridge.thumb = bridge.grid + 272, bridge.grid + 888
            else
                if active_kind then return nil, 'no visible equipment scrollbar' end
                -- A stale/hidden controller may precede the visible owner in
                -- the registry; keep looking before declaring the menu inert.
                bridge = nil
            end
            if bridge then
                bridge.key = native_key(controller) .. ':' .. tostring(kind) .. ':' .. bridge.route
                return bridge
            end
        end
    end
    -- The options pages have no equipment controller registration. Their own
    -- page pointer and active screen ID gate access to each inline list.
    local ok, bindings = pcall(function()
        local owner = api.pointer(api.read(game + 0x347ce28, 8))
        if not owner then return nil end
        local stack = api.read(owner + 0x429c, 24)
        if not stack or #stack ~= 24 then return nil end
        local function word(offset)
            local a, b, c, d = stack:byte(offset + 1, offset + 4)
            return a and d and (a + b * 256 + c * 65536 + d * 16777216)
        end
        local depth = word(20)
        if not depth or depth < 1 or depth > 5 then return nil end
        local screen_id = word((depth - 1) * 4)
        local page = OPTIONS_PAGES[screen_id]
        if not page then return nil end
        local menu = api.pointer(api.read(game + 0x347ce38, 8))
        local screen = menu and api.pointer(api.read(menu + page.menu, 8))
        if not screen or api.read(screen + 12, 1) ~= '\1' then return nil end
        local list = screen + page.list
        local bar, thumb = list + OPTIONS_LIST.bar, list + OPTIONS_LIST.thumb
        if (memory.read_f32(bar + 84) or 0) <= 0.95 then return nil end
        return {api = api, memory = memory, game = game, controller = screen,
                grid = list, bar = bar, thumb = thumb, route = page.route,
                kind = screen_id, key = native_key(screen) .. ':' .. screen_id .. ':' .. page.route}
    end)
    if ok and bindings then return bindings end
    return nil, (has_armory or has_loadout) and 'no visible equipment scrollbar'
        or 'equipment grid not registered'
end

-- native_locate with each of its reads recorded on a tape kept in the bridge.
-- native_locate decides from nothing but those reads, so while every one of
-- them returns the same bytes it would resolve the same owner again. Only the
-- shipped reader records; with another reader the tape stays empty.
function module.native_resolve(api, memory)
    local tape = {n = 0}
    api.tape = tape
    local ok, bridge, reason = pcall(module.native_locate, api, memory)
    api.tape = nil
    if not ok then error(bridge, 0) end
    if bridge then bridge.tape = tape end
    return bridge, reason
end

-- True when every read on the tape returns the bytes it recorded. Unchanged
-- bytes come back as the interned strings on the tape: no allocation.
function module.native_unchanged(api, tape)
    local count = tape and tape.n or 0
    if count == 0 then return false end
    for slot = 3, count * 3, 3 do
        if (api.read(tape[slot - 2], tape[slot - 1]) or false) ~= tape[slot] then return false end
    end
    return true
end

cs.keep_interpreted({module.native_locate, module.native_resolve, module.native_unchanged})
end
cs_files.model = function(...)
-- The owner's scroll model: its fields, read in blocks, and the track on screen.
local module, cs = ...
local GRID, BLOCK_BYTES, CAREER, OPTIONS_LIST = cs.GRID, cs.BLOCK_BYTES, cs.CAREER, cs.OPTIONS_LIST
local native_clamp, native_address = cs.native_clamp, cs.native_address

-- The model's fields by byte offset from the route's base object, grouped in
-- blocks the shipped reader fetches with one read each. A field is {name,
-- offset, float?}; a block's first byte and size cover its fields. Scrollbar
-- widgets: +12 width, +16 height, +100 and +140 UI scale, +148 left, +156
-- bottom (the thumb's rendered position).
local function seal(fields)
    local first, last = math.huge, -1
    for _, field in ipairs(fields) do
        first, last = math.min(first, field[2]), math.max(last, field[2] + 4)
    end
    for _, field in ipairs(fields) do assert((field[2] - first) % 4 == 0, 'unaligned model field') end
    assert(last - first <= BLOCK_BYTES, 'model block too large')
    fields.first, fields.size = first, last - first
    return fields
end

local function block_of(fields, ...)
    for _, field in ipairs({...}) do fields[#fields + 1] = field end
    return seal(fields)
end

local function widget_fields(bar, thumb)
    return {{'bar_width', bar + 12, true}, {'bar_height', bar + 16, true}, {'bar_sx', bar + 100, true},
            {'bar_sy', bar + 140, true}, {'bar_left', bar + 148, true}, {'bar_bottom', bar + 156, true},
            {'thumb_height', thumb + 16, true}, {'rendered_thumb', thumb + 156, true}}
end

local MODEL_LAYOUT = {
    -- From the grid; its bar widget is at +272, its thumb at +888.
    grid = {
        block_of(widget_fields(272, 888), {'span', GRID.span, true}, {'value', GRID.value, true}),
        block_of({}, {'columns', GRID.columns, false}),
        block_of({}, {'rows', GRID.rows, false}, {'selected', GRID.selected, false}, {'scroll', GRID.scroll, true},
                 {'content', GRID.content, true}, {'items', GRID.items, false}, {'kind', GRID.kind, false},
                 {'anchor', GRID.anchor, false}),
        block_of({}, {'first', GRID.first, false}, {'last', GRID.last, false}),
    },
    -- From the Career panel: its list container and its bar (track) and thumb.
    career = {
        block_of({}, {'list_x', CAREER.list + 4, true}, {'list_y', CAREER.list + 8, true},
                 {'list_height', CAREER.list + 16, true}, {'list_scale', CAREER.list + 32, true}),
        block_of(widget_fields(CAREER.track, CAREER.thumb)),
    },
    -- From the options list.
    options = {
        block_of(widget_fields(OPTIONS_LIST.bar, OPTIONS_LIST.thumb), {'scroll', OPTIONS_LIST.scroll, true},
                 {'span', OPTIONS_LIST.span, true}, {'value', OPTIONS_LIST.value, true}),
    },
}

-- The fields last read by native_state (it is never re-entered).
local raw = {}

-- One read per field: views without read_block (offline readers).
local function read_each(memory, base, layout)
    for _, block in ipairs(layout) do
        for _, field in ipairs(block) do
            local read = field[3] and memory.read_f32 or memory.read_u32
            raw[field[1]] = read(base + field[2])
        end
    end
end

-- A block that cannot be read leaves its fields nil, as a failed field read does.
local function decode_block(memory, block, loaded)
    local first, floats, words = block.first, memory.block_f32, memory.block_u32
    for _, field in ipairs(block) do
        local value = nil
        if loaded then
            local slot = (field[2] - first) / 4
            if field[3] then value = floats[slot] else value = words[slot] end
        end
        raw[field[1]] = value
    end
end

-- One read per block. The block addresses are computed once per resolved
-- owner, so a repeated read does no pointer arithmetic.
local function read_blocks(bridge, base, layout)
    local memory, addresses = bridge.memory, bridge.blocks
    if not addresses then
        addresses = {}
        for index, block in ipairs(layout) do addresses[index] = base + block.first end
        bridge.blocks = addresses
    end
    for index, block in ipairs(layout) do
        decode_block(memory, block, memory.read_block(addresses[index], block.size))
    end
end

local function read_fields(bridge, base, layout)
    if bridge.memory.read_block then return read_blocks(bridge, base, layout) end
    read_each(bridge.memory, base, layout)
end

local function off_scale(number)
    return number ~= number or math.abs(number) > GRID.max_pixels
end

-- The scrollbar's track and thumb, from raw.
local function native_geometry(model)
    local height, width, sx, sy = raw.bar_height, raw.bar_width, raw.bar_sx, raw.bar_sy
    local left, bottom, thumb = raw.bar_left, raw.bar_bottom, raw.thumb_height
    if not (height and width and sx and sy and left and bottom and thumb) then
        return nil, 'scrollbar geometry unreadable'
    end
    if off_scale(height) or off_scale(width) or off_scale(sx) or off_scale(sy) or off_scale(left)
        or off_scale(bottom) or off_scale(thumb) then return nil, 'scrollbar geometry out of range' end
    if height <= 0 or width <= 0 or sx <= 0 or sy <= 0 or thumb <= 0 or thumb >= height then
        return nil, 'scrollbar not scrollable'
    end
    model.thumb_ratio = thumb / height
    local geometry = model.geometry or {}
    geometry.left, geometry.bottom, geometry.width = left, bottom, width * sx
    geometry.length, geometry.thumb = height * sy, thumb * sy
    model.geometry = geometry
    model.rendered_thumb = raw.rendered_thumb
    return model
end

-- Career scrolls a container; the bar's height is its viewport.
local function career_model(model)
    local height, scale, viewport = raw.list_height, raw.list_scale, raw.bar_height
    local y, x = raw.list_y, raw.list_x
    if not (height and scale and viewport and y and x) then return nil, 'career unreadable' end
    local content, span = height * scale, height * scale - viewport
    if content ~= content or content > GRID.max_pixels or span ~= span or span <= 0
        or y ~= y or math.abs(y) > GRID.max_pixels or x ~= x then return nil, 'career out of range' end
    model.content, model.span, model.viewport = content, span, viewport
    model.scroll, model.list_x, model.kind = y + CAREER.padding, x, 'career'
    model.value = native_clamp((y + CAREER.padding) / span, 0, 1)
    return native_geometry(model)
end

local function options_model(model, route)
    local span, value, scroll, viewport = raw.span, raw.value, raw.scroll, raw.bar_height
    if not (span and value and scroll and viewport) or span ~= span or value ~= value
        or scroll ~= scroll or span <= 0 or span > GRID.max_pixels
        or value < -0.001 or value > 1.001 or viewport <= 0
        or viewport > GRID.max_pixels or scroll < -1 or scroll > span + 1 then
        return nil, 'bindings list out of range'
    end
    model.content, model.span, model.viewport = span + viewport, span, viewport
    model.value, model.scroll, model.kind = native_clamp(value, 0, 1), scroll, route
    return native_geometry(model)
end

local GRID_MODEL_FIELDS = {'columns', 'rows', 'items', 'kind', 'selected', 'first', 'last', 'anchor', 'content',
                           'span', 'value', 'scroll'}

-- The reason a grid's counts or pixel sizes do not fit this build, or nil.
local function grid_refusal(model)
    if not (model.columns and model.rows and model.items) then return 'grid state unreadable' end
    if model.columns < 1 or model.columns > GRID.max_columns then return 'grid columns out of range' end
    if model.rows < 1 or model.rows > GRID.max_rows then return 'grid rows out of range' end
    if model.items < 1 or model.items > GRID.max_items then return 'grid item count out of range' end
    local content, value, span = model.content, model.value, model.span
    if not content or content ~= content or content <= 0 or content > GRID.max_pixels then
        return 'grid content out of range'
    end
    if not value or value ~= value or value < -0.001 or value > 1.001 then return 'grid value out of range' end
    if not span or span ~= span or span <= 0 or span > GRID.max_pixels then return 'grid span out of range' end
    return nil
end

local function grid_model(model)
    for _, name in ipairs(GRID_MODEL_FIELDS) do model[name] = raw[name] end
    local refusal = grid_refusal(model)
    if refusal then return nil, refusal end
    model.value = native_clamp(model.value, 0, 1)
    model.viewport = model.content - model.span
    if model.viewport <= 0 then return nil, 'grid not scrollable' end
    return native_geometry(model)
end

-- Every field a model may hold except its geometry table, which a refilled
-- model keeps and overwrites.
local MODEL_FIELDS = {'columns', 'rows', 'items', 'kind', 'selected', 'first', 'last', 'anchor', 'content',
                      'span', 'value', 'scroll', 'viewport', 'list_x', 'thumb_ratio', 'rendered_thumb'}

-- Read the list's own scroll model, with the bounds the offsets were measured
-- under. A model that does not look like this build's grid is refused rather
-- than written to. With into, that table is refilled instead of a new one (a
-- held drag's live model); every field is set again, so nothing of a model of
-- another route survives.
function module.native_state(bridge, into)
    if type(bridge) ~= 'table' or not native_address(bridge.grid) or type(bridge.memory) ~= 'table' then
        return nil, 'not resolved'
    end
    local model = into or {}
    for _, name in ipairs(MODEL_FIELDS) do model[name] = nil end
    local route = bridge.route
    if route == 'career' then
        read_fields(bridge, bridge.panel, MODEL_LAYOUT.career)
        return career_model(model)
    end
    if route == 'bindings' or route == 'settings' then
        read_fields(bridge, bridge.grid, MODEL_LAYOUT.options)
        return options_model(model, route)
    end
    read_fields(bridge, bridge.grid, MODEL_LAYOUT.grid)
    return grid_model(model)
end

-- Translate the native bottom-left origin to desktop pointer coordinates.
function module.native_screen_track(model, viewport)
    local g = model and model.geometry
    if not g or not viewport or not viewport.height then return nil end
    return {left = viewport.x + g.left, right = viewport.x + g.left + g.width,
            top = viewport.y + viewport.height - g.bottom - g.length,
            length = g.length, thumb = g.thumb, span = g.length - g.thumb}
end

cs.keep_interpreted({module.native_state, read_fields, read_blocks, read_each, decode_block, native_geometry,
    career_model, options_model, grid_refusal, grid_model, off_scale, module.native_screen_track})
end
cs_files.settings = function(...)
-- The defaults, the optional ini and the scale that follows the display.
local module, cs = ...
local clamp = cs.clamp

-- --------------------------------------------------------------- settings

-- Pixel constants are quoted for a 1440 px tall viewport and scaled to the interface;
-- ini values stay absolute and the bar's measured thickness overrides the estimate.
local DEFAULTS = {
    enabled = true,
    -- Capture geometry.
    strip_width = 96,        -- px captured horizontally, centred on the cursor
    window = 460,            -- px captured vertically either side of the cursor
    window_max = 1400,       -- widest the strip may grow to when a thumb does not fit
    narrow_width = 40,       -- px wide second pass once a bar column is known
    narrow_window = 420,     -- px tall second pass
    bar_cache_ms = 60000,    -- how long a known bar column is trusted
    -- Thumb classification.
    min_height = 44,         -- shortest accepted thumb, px
    max_height_ratio = 0.94, -- longest accepted thumb, fraction of the capture
    min_width = 6,           -- narrowest accepted thumb, px
    max_width = 28,          -- widest accepted thumb, px
    min_luma = 105,          -- thumb brightness window
    max_luma = 220,
    min_luma_floor = 40,     -- absolute floor once the threshold is adapted
    min_contrast = 30,       -- thumb must be this much brighter than the strip's dark quartile
    local_contrast = true,   -- and brighter than the pixels beside it (rejects wide bright areas)
    local_offset = 16,       -- px to either side used for that comparison
    max_spread = 18,         -- max channel spread for "neutral grey"
    min_fill = 0.72,         -- fraction of grey pixels required inside a run
    max_bridge = 160,        -- masked rows a run may bridge (cursor overlay)
    max_gap = 6,             -- unmasked rows a run may bridge (small bright overlay)
    max_variance = 14,       -- max deviation from the thumb's median brightness
    min_uniformity = 0.85,   -- fraction of samples that must stay within it
    edge_contrast = 25,      -- background beside the thumb must be this much darker
    -- Click interpretation.
    thumb_margin = 9,        -- px around the thumb treated as the thumb
    column_tolerance = 12,   -- px the cursor may sit outside the thumb column
    click_contrast = 25,     -- click pixel must be this much darker than the bar
    -- Measured bounding box of the pointer's sprite: inside it, coloured or over-bright
    -- rows are bridged so the thumb stays whole under the pointer.
    cursor_mask = {x0 = -72, x1 = 72, y0 = -72, y1 = 72},
    -- Which keys follow the display scale rather than staying absolute.
    scaled_keys = {'strip_width', 'window', 'narrow_width', 'narrow_window', 'min_height', 'min_width',
                   'max_width', 'local_offset', 'max_bridge', 'max_gap', 'thumb_margin',
                   'column_tolerance', 'drag_threshold', 'drag_max_step_px',
                   'probe_step',
                   'calibration_min_px', 'calibration_max_px',
                   'center_tolerance', 'settle_stable_px'},
    cursor_mask_radius = 72, -- px, scaled with the display
    -- Aiming and following. The seed is the step measured live on the Armory list:
    -- 12.998 px of thumb travel per notch over 14 notches at the reference scale.
    default_pixels_per_notch = 13, -- measured wheel step before calibration
    bar_reference_width = 10,      -- the bar's thickness at that reference scale
    center_tolerance = 4,    -- px of aimed error that counts as centred
    jump_max_notches = 120,  -- notches one track-click jump may send
    emit_max_notches = 16,   -- notches one frame may inject; the rest follows next frame
    correction_notches = 40, -- notches one settle correction may add
    max_corrections = 2,     -- settle corrections per jump, each of which must shrink the error
    settle_delay_ms = 200,   -- wait after a jump before measuring the thumb
    settle_interval_ms = 60, -- between settle measurements
    settle_stable_px = 2,    -- movement below this counts as stopped
    settle_checks = 8,       -- measurements before a jump is given up
    drag_threshold = 10,     -- px of vertical movement that starts a drag
    drag_max_step_px = 220,  -- a larger single-frame jump is a pointer teleport
    drag_max_notches = 40,   -- hard cap on the notches one drag frame may send
    -- Accepted for older INIs; wheel input now stays inside the exact column.
    drag_column_margin = 2.8,
    drag_verify_notches = 3, -- notches before a drag re-checks the thumb
    -- Gap between drag re-checks: each costs ~1.9 ms measured, and every check skipped
    -- is another stretch of notches spent past a thumb the game has clamped.
    drag_verify_ms = 45,
    drag_stall_confirmations = 2, -- readings in a row that must show no thumb movement
    track_clamp_max_notches = 12,  -- notches a learned track end may block before it is dropped
    -- Drive the value and run the layout solver together. The old bare value
    -- write could move only the thumb; the solver also updates the visible rows.
    native = 1,
    native_verify_ms = 200,
    calibration_samples = 7, -- observed steps kept for the median
    calibration_min_px = 4,  -- accepted observed px/notch window
    calibration_max_px = 60,
    -- Diagnostics.
    trace_lines = 48,        -- decisions kept for the log
    trace_events = 0,        -- 1 records every emission and drag step
    diagnostics = 0,         -- opt-in interaction traces and periodic disk writes
    log_interval_ms = 5000,  -- shortest gap between log writes
    cooldown_ms = 0,         -- shortest gap between two track-click jumps
    min_capture_interval_ms = 40,
    use_window_capture = 1,  -- 1 tries the game's own window DC before the desktop DC
    scale_geometry = 1,      -- 1 scales the pixel geometry to the display height
    probe_step = 8,             -- rows between column probes (a run is far taller)
    -- Captures are the only expensive work here; a press on a bar that was already
    -- measured is answered from that analysis and the notches sent since.
    burst_cache_ms = 250,       -- how long a recent analysis may classify a press
    burst_capture_every = 3,    -- force a real capture after this many skips
    capture_budget_ms_per_s = 60, -- capture time the addon may spend per second
    capture_budget_floor_ms_per_s = 30, -- floor for that budget when frames are slow
    error_limit = 8,         -- frame errors in one burst that stop the addon
    dump_captures = 0,       -- diagnostic BMP dumps; 0 keeps nothing on disk
}

function module.parse_settings(text, base) -- lint-ok: R10 moved unchanged from the single file; existing debt, not new
    local settings = {}
    for key, value in pairs(base or DEFAULTS) do settings[key] = value end
    -- Keys that came from the ini hold absolute device pixels and are never
    -- scaled: a value the user typed means exactly what it says.
    local overridden = {}
    if type(text) == 'string' then
        for line in text:gmatch('[^\r\n]+') do
            local key, value = line:match('^%s*([%a_]+)%s*=%s*([%-%d%.]+)%s*$')
            if key and DEFAULTS[key] ~= nil and type(DEFAULTS[key]) ~= 'table' then
                local number = tonumber(value)
                if number then
                    overridden[key] = true
                    if type(DEFAULTS[key]) == 'boolean' then
                        settings[key] = number ~= 0
                    else
                        settings[key] = number
                    end
                end
            end
        end
    end
    settings.overridden = overridden
    return module.clamp_settings(settings)
end

-- Bounds every value so a hostile or careless ini cannot produce a geometry the
-- detector or the capture surface cannot honour.
function module.clamp_settings(settings)
    settings.strip_width = clamp(math.floor(settings.strip_width), 32, 240)
    settings.window = clamp(math.floor(settings.window), 120, 1400)
    settings.window_max = clamp(math.floor(settings.window_max), settings.window, 1400)
    settings.narrow_width = clamp(math.floor(settings.narrow_width), 16, 120)
    settings.narrow_window = clamp(math.floor(settings.narrow_window), 120, 1400)
    settings.bar_cache_ms = clamp(math.floor(settings.bar_cache_ms), 0, 600000)
    settings.min_height = clamp(math.floor(settings.min_height), 12, 1200)
    settings.max_height_ratio = clamp(settings.max_height_ratio, 0.1, 1)
    settings.min_width = clamp(math.floor(settings.min_width), 3, 60)
    settings.max_width = clamp(math.floor(settings.max_width), settings.min_width, 80)
    settings.min_luma = clamp(math.floor(settings.min_luma), 30, 250)
    settings.max_luma = clamp(math.floor(settings.max_luma), settings.min_luma + 5, 255)
    settings.min_luma_floor = clamp(math.floor(settings.min_luma_floor), 10, 240)
    settings.min_contrast = clamp(math.floor(settings.min_contrast), 5, 200)
    settings.local_contrast = settings.local_contrast and true or false
    settings.local_offset = clamp(math.floor(settings.local_offset), 4, 200)
    settings.max_spread = clamp(math.floor(settings.max_spread), 2, 120)
    settings.min_fill = clamp(settings.min_fill, 0.2, 1)
    settings.max_bridge = clamp(math.floor(settings.max_bridge), 0, 400)
    settings.max_gap = clamp(math.floor(settings.max_gap), 0, 400)
    settings.max_variance = clamp(math.floor(settings.max_variance), 1, 120)
    settings.min_uniformity = clamp(settings.min_uniformity, 0.1, 1)
    settings.edge_contrast = clamp(math.floor(settings.edge_contrast), 0, 200)
    settings.thumb_margin = clamp(math.floor(settings.thumb_margin), 0, 200)
    settings.column_tolerance = clamp(math.floor(settings.column_tolerance), 0, 120)
    settings.click_contrast = clamp(math.floor(settings.click_contrast), 0, 200)
    settings.default_pixels_per_notch = clamp(settings.default_pixels_per_notch, 4, 400)
    settings.bar_reference_width = clamp(settings.bar_reference_width, 2, 60)
    settings.center_tolerance = clamp(math.floor(settings.center_tolerance), 0, 100)
    settings.jump_max_notches = clamp(math.floor(settings.jump_max_notches), 1, 2000)
    settings.emit_max_notches = clamp(math.floor(settings.emit_max_notches), 1, 2000)
    settings.correction_notches = clamp(math.floor(settings.correction_notches), 1, 200)
    settings.max_corrections = clamp(math.floor(settings.max_corrections), 0, 30)
    settings.settle_delay_ms = clamp(math.floor(settings.settle_delay_ms), 20, 5000)
    settings.settle_interval_ms = clamp(math.floor(settings.settle_interval_ms), 10, 2000)
    settings.settle_stable_px = clamp(settings.settle_stable_px, 0, 100)
    settings.settle_checks = clamp(math.floor(settings.settle_checks), 1, 50)
    settings.drag_threshold = clamp(math.floor(settings.drag_threshold), 2, 200)
    settings.drag_max_step_px = clamp(math.floor(settings.drag_max_step_px), 20, 2000)
    settings.drag_max_notches = clamp(math.floor(settings.drag_max_notches), 1, 400)
    settings.drag_column_margin = clamp(settings.drag_column_margin, 0.5, 40)
    settings.drag_verify_notches = clamp(math.floor(settings.drag_verify_notches), 1, 100)
    settings.drag_verify_ms = clamp(math.floor(settings.drag_verify_ms), 20, 5000)
    settings.drag_stall_confirmations = clamp(math.floor(settings.drag_stall_confirmations), 1, 10)
    settings.track_clamp_max_notches = clamp(math.floor(settings.track_clamp_max_notches), 0, 400)
    settings.native = clamp(math.floor(settings.native), 0, 1)
    settings.native_verify_ms = clamp(math.floor(settings.native_verify_ms), 20, 2000)
    settings.calibration_samples = clamp(math.floor(settings.calibration_samples), 1, 25)
    settings.calibration_min_px = clamp(settings.calibration_min_px, 1, 200)
    settings.calibration_max_px = clamp(settings.calibration_max_px, settings.calibration_min_px, 400)
    settings.trace_lines = clamp(math.floor(settings.trace_lines), 0, 500)
    settings.trace_events = clamp(math.floor(settings.trace_events), 0, 1)
    settings.log_interval_ms = clamp(math.floor(settings.log_interval_ms), 0, 60000)
    settings.cooldown_ms = clamp(math.floor(settings.cooldown_ms), 0, 5000)
    settings.min_capture_interval_ms = clamp(math.floor(settings.min_capture_interval_ms), 0, 5000)
    settings.use_window_capture = clamp(math.floor(settings.use_window_capture), 0, 1)
    settings.scale_geometry = clamp(math.floor(settings.scale_geometry), 0, 1)
    settings.probe_step = clamp(math.floor(settings.probe_step), 1, 64)
    settings.burst_cache_ms = clamp(math.floor(settings.burst_cache_ms), 0, 2000)
    settings.burst_capture_every = clamp(math.floor(settings.burst_capture_every), 1, 100)
    settings.capture_budget_ms_per_s = clamp(math.floor(settings.capture_budget_ms_per_s), 0, 5000)
    settings.capture_budget_floor_ms_per_s = clamp(math.floor(settings.capture_budget_floor_ms_per_s), 0, 5000)
    settings.error_limit = clamp(math.floor(settings.error_limit), 1, 1000)
    settings.dump_captures = clamp(math.floor(settings.dump_captures), 0, 50)
    settings.cursor_mask_radius = clamp(settings.cursor_mask_radius, 24, 320)
    settings.cursor_mask = {
        x0 = -math.floor(settings.cursor_mask_radius), x1 = math.ceil(settings.cursor_mask_radius),
        y0 = -math.floor(settings.cursor_mask_radius), y1 = math.ceil(settings.cursor_mask_radius),
    }
    settings.enabled = settings.enabled and true or false
    return settings
end

-- The reference geometry was measured on a 1440 px tall viewport, which the
-- interface was assumed to follow; the bar's measured thickness corrects that.
local REFERENCE_HEIGHT = 1440

function module.scale_for_height(height)
    if type(height) ~= 'number' or height < 240 then return 1 end
    return clamp(height / REFERENCE_HEIGHT, 0.4, 4)
end

function module.scale_settings(base, scale)
    local scaled = {}
    for key, value in pairs(base) do scaled[key] = value end
    scaled.scale = scale
    if scale == 1 then return module.clamp_settings(scaled) end
    for _, key in ipairs(DEFAULTS.scaled_keys) do
        if not (base.overridden and base.overridden[key]) then
            scaled[key] = base[key] * scale
        end
    end
    if not (base.overridden and base.overridden.cursor_mask_radius) then
        scaled.cursor_mask_radius = base.cursor_mask_radius * scale
    end
    return module.clamp_settings(scaled)
end

-- For the runtime.
cs.DEFAULTS = DEFAULTS
end
cs_files.platform = function(...)
-- The Windows functions the runtime calls, declared under private names.
local module = ...

-- --------------------------------------------------------------- platform

-- The Windows functions the platform calls, by library. Each is declared under a
-- private name (__asm__ label): LuaJIT keeps the first prototype declared for a
-- name in the whole process, so a mod that declared GetCursorPos(int32_t *) first
-- broke v2.14. No GDI function and no input synthesis: the screen-capture and
-- wheel routes that needed them are gone from the runtime.
module.platform_functions = {
    user32 = {'GetCursorPos', 'GetAsyncKeyState', 'GetForegroundWindow', 'GetSystemMetrics',
              'GetWindowThreadProcessId', 'GetClientRect', 'ClientToScreen', 'IsWindow'},
    kernel32 = {'GetCurrentProcessId', 'GetTickCount64'},
}

local PLATFORM_DECLARATIONS = [[
    typedef struct { int x; int y; } HD2CS_POINT;
    typedef struct { int left; int top; int right; int bottom; } HD2CS_RECT;
    int hd2cs_GetCursorPos(HD2CS_POINT *point) __asm__("GetCursorPos");
    short hd2cs_GetAsyncKeyState(int key) __asm__("GetAsyncKeyState");
    void *hd2cs_GetForegroundWindow(void) __asm__("GetForegroundWindow");
    int hd2cs_GetSystemMetrics(int index) __asm__("GetSystemMetrics");
    unsigned int hd2cs_GetCurrentProcessId(void) __asm__("GetCurrentProcessId");
    unsigned int hd2cs_GetWindowThreadProcessId(void *window, unsigned int *process)
        __asm__("GetWindowThreadProcessId");
    int hd2cs_GetClientRect(void *window, HD2CS_RECT *rect) __asm__("GetClientRect");
    int hd2cs_ClientToScreen(void *window, HD2CS_POINT *point) __asm__("ClientToScreen");
    int hd2cs_IsWindow(void *window) __asm__("IsWindow");
    unsigned long long hd2cs_GetTickCount64(void) __asm__("GetTickCount64");
]]

-- Binds one library's functions by their real names; a missing export is a named
-- startup error.
local function bind_library(ffi, library)
    local loaded, bound = ffi.load(library), {}
    for _, name in ipairs(module.platform_functions[library]) do
        local found, fn = pcall(function() return loaded['hd2cs_' .. name] end)
        if not found then error(library .. '.' .. name .. ' unavailable', 0) end
        bound[name] = fn
    end
    return bound
end

-- libraries, for tests: {user32 = ..., kernel32 = ...} tables holding the
-- functions above; the shipped call binds the real ones.
function module.create_platform(libraries)
    local ffi = require('ffi')
    local bit = require('bit')
    assert(ffi.abi('64bit'), 'Windows x64 is required')
    -- Declared once per process, so a second platform (a test) can be created.
    if not pcall(ffi.typeof, 'HD2CS_RECT') then ffi.cdef(PLATFORM_DECLARATIONS) end
    local user32 = libraries and libraries.user32 or bind_library(ffi, 'user32')
    local kernel32 = libraries and libraries.kernel32 or bind_library(ffi, 'kernel32')

    -- LuaJIT resolves each imported symbol on first use, so every binding is
    -- exercised once here: a wrong library or a missing export must surface as
    -- a named startup error instead of failing on the first click.
    local function check(name, fn, ...)
        local ok, value = pcall(fn, ...)
        if not ok then error(name .. ': ' .. tostring(value), 0) end
        return value
    end
    check('GetTickCount64', function() return kernel32.GetTickCount64() end)
    local process_id = check('GetCurrentProcessId', function() return kernel32.GetCurrentProcessId() end)
    check('GetAsyncKeyState', function() return user32.GetAsyncKeyState(0) end)
    check('GetForegroundWindow', function() return user32.GetForegroundWindow() end)
    check('GetSystemMetrics', function() return user32.GetSystemMetrics(0) end)
    -- Indexing a loaded library resolves the symbol, so a missing export still
    -- surfaces at startup - without calling it with a null window handle.
    for _, name in ipairs({'IsWindow', 'GetClientRect', 'ClientToScreen'}) do
        if user32[name] == nil then error('user32.' .. name .. ' unavailable', 0) end
    end
    -- The virtual desktop's height answers display_height when the foreground
    -- window gives none.
    local SM_CYVIRTUALSCREEN = 79
    local virtual_height = user32.GetSystemMetrics(SM_CYVIRTUALSCREEN)
    local point = ffi.new('HD2CS_POINT[1]')
    -- Declared later, a shared scratch buffer is a global inside the function and
    -- indexing it raises (the v2.2 "attempt to index global 'rect'" crash).
    local rect, client_origin = ffi.new('HD2CS_RECT[1]'), ffi.new('HD2CS_POINT[1]')
    -- The foreground window's process id, asked every frame: one buffer, no garbage.
    local window_process = ffi.new('unsigned int[1]')

    local platform = {}

    check('GetCursorPos', function() return user32.GetCursorPos(point) end)

    function platform.now()
        return tonumber(kernel32.GetTickCount64())
    end

    function platform.cursor()
        if user32.GetCursorPos(point) == 0 then return nil end
        return point[0].x, point[0].y
    end

    -- Height of the game's own viewport, read in the same coordinate space as the
    -- cursor. The interface does not follow it exactly; the bar's measured
    -- thickness is the better scale.
    function platform.display_height()
        local window = user32.GetForegroundWindow()
        if window ~= nil and user32.IsWindow(window) ~= 0 and user32.GetClientRect(window, rect) ~= 0 then
            local height = rect[0].bottom - rect[0].top
            if height >= 240 then return height end
        end
        if virtual_height >= 240 then return virtual_height end
        return nil
    end

    function platform.viewport()
        local window = user32.GetForegroundWindow()
        if window == nil or user32.GetClientRect(window, rect) == 0 then return nil end
        client_origin[0].x, client_origin[0].y = 0, 0
        if user32.ClientToScreen(window, client_origin) == 0 then return nil end
        return {x = tonumber(client_origin[0].x), y = tonumber(client_origin[0].y),
                width = tonumber(rect[0].right), height = tonumber(rect[0].bottom)}
    end

    function platform.pressed()
        return bit.band(user32.GetAsyncKeyState(0x01), 0x8000) ~= 0
    end


    -- Raw two-byte GetAsyncKeyState value for VK_LBUTTON, for diagnostics
    -- (0x8000 = down now, 0x0001 = pressed since the previous query).
    function platform.key_state()
        local value = user32.GetAsyncKeyState(0x01)
        if value < 0 then value = value + 65536 end
        return value
    end

    function platform.foreground_self()
        local window = user32.GetForegroundWindow()
        if window == nil then return false end
        -- Cleared first: a failed call leaves the buffer unwritten, which must read
        -- as another process, not as the previous answer.
        window_process[0] = 0
        user32.GetWindowThreadProcessId(window, window_process)
        return window_process[0] == process_id
    end

    -- Nothing to release: the platform holds no device context or bitmap.
    function platform.close() end

    return platform
end
end
cs_files.install = function(...)
-- The runtime the loader starts: presses, held drags, the log and the error
-- policy, in the game's update callback.
local module, cs = ...
local clamp, DEFAULTS, keep_interpreted, runtime = cs.clamp, cs.DEFAULTS, cs.keep_interpreted, cs.runtime
local bingus_memory = cs.bingus_memory

-- ---------------------------------------------------------------- build gate

-- Build 25480438's module hashes: helldivers2.exe and game.dll.
module.BUILD = {exe_sha256 = 'F5FEE03DCFDB2E553A4752C283590950AC13316B376D8196AA556FF0400D5F06',
                game_sha256 = '2E2C3B7C2500646DADD5F2B4C6E0504DBB7E7896139F64CDDC0D1813C718F51E'}

-- Bingus Shared Runtime's read side (bingus_memory.lua, vendored), used only
-- for the build check.
function module.build_memory()
    return bingus_memory.new(runtime)
end

-- True, or false and why. Hashes the two module files once per session for
-- every mod that asks (BingusRuntime.hashes). memory: for tests.
function module.verify_build(memory)
    local ran, verified, why = pcall(function()
        return (memory or module.build_memory()).verify_build(module.BUILD)
    end)
    if not ran then return false, tostring(verified) end
    if verified then return true end
    if why == 'unsupported game build' then return false, 'unsupported game build (needs Steam build 25480438)' end
    return false, tostring(why)
end

-- ------------------------------------------------------------------ install

-- The native route needs only a reader: the addon builds that itself with the
-- same FFI surface the shipped Armory mods use, and the loader may hand one in.
-- The armory grid exists only while its screen does, so this first attempt is
-- for the log; the press path retries through refresh_native.
local function attach_native(state, platform)
    if state.bridge and state.bridge.api then
        state.native_api = state.bridge.api
    else
        local ok, api, reason = pcall(module.native_api)
        if ok and type(api) == 'table' then
            state.native_api = api
        else
            state.native_reason = tostring(reason or api)
        end
    end
    state.native_api_attempted = true
    if state.native_api then
        state.native, state.native_reason = module.native_locate(state.native_api)
        state.native_try = platform.now()
        if state.native then
            state.native_model, state.native_state_reason = module.native_state(state.native)
        end
    end
end

-- Error-free frames that end a burst of frame errors (about a minute at 60 FPS).
local ERROR_BURST_FRAMES = 3600

function module.install(create_platform, environment)
    local environment = environment or _G
    local loader = rawget(environment, 'CowboyBingusModLoader')
    if type(loader) ~= 'table' or (loader.api or 0) < 1 then
        return nil, 'Bingus Shared Loader API 1 is required'
    end
    if rawget(environment, 'ClickableScrollbars') then
        return nil, 'already installed'
    end
    if type(environment.update) ~= 'function' then
        return nil, 'game update callback unavailable'
    end

    local state = {
        revision = module.revision, status = 'starting', settings = module.parse_settings(nil, DEFAULTS),
        clicks = 0, pages = 0, drags = 0, corrections = 0, no_response = 0, misses = 0, skipped = 0,
        capture_failures = 0, errors = 0, burst_errors = 0, frames = 0, down_frames = 0, frame_clicks = 0,
        last_key = 0,
        wheel_units = 0, drag_notches = 0, drag_active = false,
        captures = 0, dumps = 0, last_dump = nil,
        wide_retries = 0, capture_fallbacks = 0,
        geometry_failures = 0, geometry_failed = false,
        emit_clamps = 0,
        settle_budget_skips = 0, frame_interval_ms = nil, effective_budget_ms_per_s = nil,
        drag_verifies = 0, drag_stalls = 0, drag_limits = 0, drag_out = 0, drag_rejects = 0,
        drag_resyncs = 0,
        track_top = nil, track_bottom = nil, track_column = nil, track_blocked = 0,
        track_drops = 0, drag_foreground_pauses = 0,
        burst_skips = 0, budget_skips = 0, capture_window_start = nil, capture_window_ms = 0,
        frame_ms_total = 0, frame_ms_max = 0, capture_ms_total = 0, capture_ms_max = 0,
        dirty = true, last_reason = 'start', last_direction = nil, last_bar = nil, last_notches = 0,
        last_delta = nil, last_moved = nil, last_luminance = nil, last_background = nil,
        last_click_luma = nil, last_bar_luma = nil,
        last_thumb_masked = nil, bar_cache = nil, last_error = nil,
        pixels_per_notch = nil, calibration = {},
    }
    rawset(environment, 'ClickableScrollbars', state)

    -- The build gate, before the platform, the UI bridge, the reader or the
    -- ini: on any other build the addon only logs why (the caller writes the
    -- status) and hooks nothing. The game.dll signature checks stay after it.
    local verified, why = module.verify_build()
    if not verified then
        state.status = 'disabled: ' .. why
        return nil, state.status
    end

    local function read_settings()
        local base = os.getenv('LOCALAPPDATA')
        if not base then return state.settings end
        local path = base .. '/ClickableScrollbars'
        local file = io.open(path .. '/ClickableScrollbars.ini', 'rb')
        if not file then return state.settings end
        local text = file:read(4096)
        file:close()
        return module.parse_settings(text, DEFAULTS)
    end

    local created, platform = pcall(create_platform)
    if not created then
        state.status = 'disabled: ' .. tostring(platform)
        return nil, state.status
    end

    -- The UI bridge, if the loader hands this addon its API factory. It is what the
    -- new architecture drives; without it the addon does not synthesise a drag at all,
    -- because a synthesised one cannot avoid pressing whatever the pointer crosses.
    local factory = environment.create_api or (loader and loader.create_api)
    state.bridge, state.bridge_reason = module.ui_bridge(factory)
    attach_native(state, platform)
    -- The ini is read once and kept as the base; the effective settings are the
    -- base at the current display scale, so a resolution change can be followed
    -- without re-reading anything.
    state.base_settings = read_settings()
    state.settings = state.base_settings
    state.status = state.settings.enabled and 'running' or 'disabled: config'

    local last_button = false
    local last_frame_ms, last_log_ms = -1, -100000
    -- thumb, jump and injected_total belonged to the removed wheel route and stay
    -- nil, nil and 0: begin_drag and the log still read them, so the drag record
    -- and the log keep their fields.
    local drag, thumb, jump = nil, nil, nil
    -- Input capture outlives a cancelled scroll until the physical mouse-up.
    -- Releasing over another control must not turn the old hold into a click.
    local settings_capture
    local injected_total = 0
    local trace, reason_counts = {}, {}
    local function note(reason)
        state.last_reason = reason
        state.dirty = true
        reason_counts[reason] = (reason_counts[reason] or 0) + 1
    end

    -- The log is the flight recorder: settings, counters, health, geometry,
    -- calibration, reason tally, trace. Rewritten, never grown.
    local function log(force)
        -- The clock is read only when the log may be written: frame() calls this
        -- every frame, and without diagnostics nothing is written.
        if not force and (state.settings.diagnostics ~= 1 or not state.dirty) then return end
        local now = platform.now()
        if not force and now - last_log_ms < state.settings.log_interval_ms then return end
        last_log_ms, state.dirty = now, false
        pcall(function() -- lint-ok: R10 moved unchanged from the single file; existing debt, not new
            local file = loader.open_log and loader.open_log('ClickableScrollbars.log')
            if not file then return end
            local out = {}
            local function put(fmt, ...) out[#out + 1] = string.format(fmt, ...) end
            put('%s', state.revision)
            put('status=%s', state.status)
            if state.last_error then put('error=%s', state.last_error) end
            put('--- settings')
            put('scale=%s', tostring(state.scale or 1))
            put('display_height=%s', tostring(state.display_height or 'unknown'))
            for _, key in ipairs({'enabled', 'center_tolerance', 'jump_max_notches', 'correction_notches',
                                  'max_corrections', 'settle_delay_ms', 'settle_interval_ms', 'settle_stable_px',
                                  'settle_checks', 'drag_threshold', 'drag_max_step_px', 'drag_max_notches',
                                  'calibration_samples', 'calibration_min_px', 'calibration_max_px',
                                  'cooldown_ms', 'min_capture_interval_ms', 'log_interval_ms', 'trace_lines',
                                  'trace_events', 'use_window_capture', 'error_limit', 'dump_captures',
                                  'strip_width', 'window', 'narrow_width',
                                  'narrow_window', 'min_height', 'min_width', 'max_width', 'min_luma', 'max_luma',
                                  'min_contrast', 'click_contrast', 'thumb_margin', 'column_tolerance',
                                  'bar_cache_ms', 'window_max', 'probe_step', 'burst_cache_ms',
                                  'burst_capture_every', 'capture_budget_ms_per_s', 'scale_geometry',
                                  'cursor_mask_radius', 'emit_max_notches',
                                  'capture_budget_floor_ms_per_s',
                                  'drag_column_margin',
                                  'drag_verify_notches', 'drag_verify_ms', 'drag_stall_confirmations',
                                  'native', 'native_verify_ms'}) do
                put('%s=%s', key, tostring(state.settings[key]))
            end
            put('--- counters')
            for _, key in ipairs({'clicks', 'pages', 'drags', 'corrections', 'no_response', 'misses', 'skipped',
                                  'capture_failures', 'errors', 'frames', 'down_frames', 'frame_clicks',
                                  'wheel_units', 'drag_notches', 'burst_skips', 'budget_skips',
                                  'emit_clamps', 'settle_budget_skips', 'drag_verifies', 'drag_stalls',
                                  'drag_limits', 'drag_out', 'drag_rejects', 'mask_retries', 'track_drops',
                                  'drag_foreground_pauses', 'settle_unfocused', 'drag_resyncs',
                                  'native_writes', 'native_ok', 'native_fallbacks'}) do
                put('%s=%d', key, state[key] or 0)
            end
            put('--- health')
            put('capture_source=%s', tostring(state.capture_source or 'window'))
            put('capture_fallbacks=%d', state.capture_fallbacks or 0)
            put('wide_retries=%d', state.wide_retries or 0)
            put('geometry_failures=%d', state.geometry_failures or 0)
            put('capture_ms_per_s=%d', state.capture_window_ms or 0)
            put('capture_share_pct=%.1f', (state.capture_window_ms or 0) / 10)
            put('budget_effective=%s', tostring(math.floor(state.effective_budget_ms_per_s
                or state.settings.capture_budget_ms_per_s)))
            put('game_fps=%s', state.frame_interval_ms and string.format('%.0f', 1000 / state.frame_interval_ms)
                or 'unknown')
            put('captures=%d', state.captures)
            put('capture_ms_max=%d', state.capture_ms_max)
            put('capture_ms_avg=%.3f', state.captures > 0 and state.capture_ms_total / state.captures or 0)
            put('frame_ms_max=%d', state.frame_ms_max)
            put('frame_ms_avg=%.4f', state.frames > 0 and state.frame_ms_total / state.frames or 0)
            put('--- state')
            put('drag_active=%s', tostring(state.drag_active or false))
            put('jump_active=%s', tostring(jump ~= nil))
            put('injected_since_observe=%d', injected_total - (thumb and thumb.injected_at or injected_total))
            put('last_reason=%s', tostring(state.last_reason))
            put('last_direction=%s', tostring(state.last_direction or 'none'))
            put('last_notches=%d', state.last_notches or 0)
            put('last_delta=%s', tostring(state.last_delta or 'none'))
            put('last_moved=%s', tostring(state.last_moved or 'none'))
            put('pixels_per_notch=%s', state.pixels_per_notch and string.format('%.2f', state.pixels_per_notch)
                or 'none')
            local samples = {}
            for index = 1, #state.calibration do samples[index] = string.format('%.2f', state.calibration[index]) end
            put('calibration=%s', #samples > 0 and table.concat(samples, ',') or 'none')
            local bar = state.last_bar
            put('last_bar=%s', bar and (bar.left .. ',' .. bar.top .. ',' .. bar.right .. ',' .. bar.bottom)
                or 'none')
            put('last_bar_masked=%s', tostring(state.last_thumb_masked or false))
            local cache = state.bar_cache
            put('bar_cache=%s', cache and (cache.left .. ',' .. cache.right) or 'none')
            local tracked = thumb
            put('thumb=%s', tracked and string.format('%d..%d centre=%.1f height=%s', tracked.left, tracked.right,
                tracked.center_y, tostring(tracked.height)) or 'none')
            put('track_top=%s', state.track_top and string.format('%.1f', state.track_top) or 'none')
            put('track_bottom=%s', state.track_bottom and string.format('%.1f', state.track_bottom) or 'none')
            put('drag_held=%s', drag and (drag.held_units == 1 and 'up' or (drag.held_units == -1 and 'down'
                or 'none')) or 'none')
            -- The measured interface ruler: the bar's thickness against its
            -- reference thickness on the machine the constants were measured on.
            put('ui_ruler=%s', state.ruler and string.format('%.3f', state.ruler) or 'none')
            put('ui_bridge=%s', state.bridge and string.format('ui=%s dispatch=%s', tostring(state.bridge.ui),
                tostring(state.bridge.dispatch)) or ('none (' .. tostring(state.bridge_reason) .. ')'))
            if state.native then
                local model = state.native_model
                put('native grid=%s state=%s', tostring(state.native.key or 'resolved'),
                    state.native_failed and 'retired' or 'active')
                put('native model value=%s scroll=%s span=%s content=%s viewport=%s'
                    .. ' first=%s last=%s anchor=%s items=%s rows=%s columns=%s',
                    model and string.format('%.4f', model.value) or 'none',
                    model and string.format('%.1f', model.scroll or -1) or 'none',
                    model and string.format('%.1f', model.span) or 'none',
                    model and string.format('%.1f', model.content) or 'none',
                    model and string.format('%.1f', model.viewport) or 'none',
                    tostring(model and model.first), tostring(model and model.last),
                    tostring(model and model.anchor),
                    tostring(model and model.items), tostring(model and model.rows),
                    tostring(model and model.columns))
                put('native last_value=%s track=%s', state.native_value and string.format('%.4f', state.native_value)
                    or 'none', tostring(state.native_state_reason or 'read'))
            else
                put('native none (%s)', tostring(state.native_reason))
            end
            put('last_luminance=%s', tostring(state.last_luminance or 'none'))
            put('last_click_luma=%s', state.last_click_luma and string.format('%.1f', state.last_click_luma)
                or 'none')
            put('last_bar_luma=%s', state.last_bar_luma and string.format('%.1f', state.last_bar_luma) or 'none')
            put('background_luma=%s', tostring(state.last_background or 'none'))
            put('last_dump=%s', tostring(state.last_dump or 'none'))
            local names = {}
            for name in pairs(reason_counts) do names[#names + 1] = name end
            table.sort(names)
            local summary = {}
            for _, name in ipairs(names) do
                summary[#summary + 1] = name .. '=' .. reason_counts[name]
            end
            put('reason_counts=%s', #summary > 0 and table.concat(summary, ',') or 'none')
            put('--- trace')
            put('trace_lines=%d', #trace)
            for _, line in ipairs(trace) do put('trace %s', line) end
            file:write(table.concat(out, '\n') .. '\n')
            file:close()
        end)
    end

    local function record(fmt, ...)
        if state.settings.diagnostics ~= 1 then return end
        local line = select('#', ...) > 0 and string.format(fmt, ...) or fmt
        trace[#trace + 1] = string.format('%d %s', math.floor(platform.now()), line)
        while #trace > state.settings.trace_lines do table.remove(trace, 1) end
        state.dirty = true
    end

    -- The budget is a share of frame time, not a capture count, with a floor so the
    -- feature never stops answering. Only the log reads it now (budget_effective).
    local function refresh_budget()
        local configured = state.settings.capture_budget_ms_per_s
        if configured <= 0 then
            state.effective_budget_ms_per_s = 0
            return
        end
        local interval = state.frame_interval_ms
        local budget = configured
        if interval and interval > 20 then
            budget = configured * (20 / interval)
        end
        budget = math.max(state.settings.capture_budget_floor_ms_per_s, budget)
        if budget > configured then budget = configured end
        state.effective_budget_ms_per_s = budget
    end

    -- Geometry follows the display height and is re-derived whenever it changes, so a
    -- monitor or resolution change is picked up on the next press.
    local function refresh_geometry(force) -- lint-ok: R10 moved unchanged from the single file; existing debt, not new
        -- A display query must never be able to stop the addon: a driver or
        -- Windows quirk here costs the scale, not the feature. The failure is
        -- counted and logged once per state change.
        local height = nil
        if platform.display_height then
            local ok, value = pcall(platform.display_height)
            if ok then
                height = value
                if state.geometry_failed then
                    state.geometry_failed = false
                    record('display query recovered after %d failures', state.geometry_failures or 0)
                end
            else
                state.geometry_failures = (state.geometry_failures or 0) + 1
                if not state.geometry_failed then
                    state.geometry_failed = true
                    record('display query failed: %s', tostring(value))
                end
            end
        end
        if not height then return false end
        local guess = state.settings.scale_geometry == 1 and module.scale_for_height(height) or 1
        -- The display height is only a guess: the bar's measured thickness corrects it
        -- within a factor of two, while the display it was measured on is unchanged.
        -- The measurement may correct the guess downwards, never upwards: a larger
        -- capture window sees more of the screen, and a false bar-like run of the
        -- wrong thickness must not be able to widen it.
        local ruler = state.ruler
        if ruler and state.ruler_height and math.abs(state.ruler_height - height) > 0.02 * height then
            ruler, state.ruler = nil, nil
        end
        local scale = ruler and math.min(guess, clamp(ruler, guess / 2, guess * 2)) or guess
        if not force and state.scale and math.abs(scale - state.scale) <= 0.02 * state.scale then return false end
        local first = state.scale == nil
        local moved_display = state.display_height ~= nil and math.abs(state.display_height - height) > 0.02 * height
        state.display_height, state.scale = height, scale
        state.settings = module.scale_settings(state.base_settings, scale)
        if not first then
            state.bar_cache, state.thumb_height, state.pixels_per_notch = nil, nil, nil
            state.calibration = {}
            if moved_display then state.ruler = nil end
            record('geometry changed scale=%.3f height=%d window=%d strip=%d mask=%d step=%.1f', scale, height,
                   state.settings.window, state.settings.strip_width, state.settings.cursor_mask_radius,
                   state.settings.default_pixels_per_notch)
            state.dirty = true
        end
        return true
    end

    -- The drag record; begin_native_drag adds the native fields. The anchor, column
    -- and wheel-step fields served the removed wheel route and keep the record's shape.
    local function begin_drag(cursor_x, cursor_y, now, left, right, side, unmeasured, track) -- lint-ok: R12 moved unchanged from the single file; existing debt, not new
        local centre = thumb and thumb.center_y or nil
        drag = {start_x = cursor_x, start_y = cursor_y, last_y = cursor_y, last_raw_y = cursor_y,
                unmeasured = unmeasured, active = false,
                fraction = 0, total = 0, verified_at = now, verified_units = injected_total,
                observed_centre = centre, observe_units = injected_total,
                anchor_y = cursor_y, anchor_centre = centre,
                column_left = left, column_right = right,
                track_top = track and track.top or nil,
                track_bottom = track and (track.top + track.length) or nil}
    end

    -- The native route's one gesture: while the button is held the list's own
    -- scroll value follows the pointer, so the thumb moves by the distance the
    -- pointer moved and nothing is injected anywhere. The first write of a
    -- gesture is checked against the game's read-back. A failed route is retired
    -- for that controller until a press resolves a different one.
    local function native_retire(reason)
        state.native_failed = true
        state.native_failed_key = state.native and state.native.key
        state.native_fallbacks = (state.native_fallbacks or 0) + 1
        note('native_retired')
        record('native retired (%s) after %d writes', tostring(reason), state.native_writes or 0)
    end

    -- The two tables a hold refreshes its model into, in turn: the press
    -- snapshot stays immutable, and state.native_model always holds the last
    -- model that passed.
    local live_models = {{}, {}}

    -- A controller can disappear or be reused for another category during a
    -- hold. Re-validate before writing; plausible stale memory is not proof
    -- that this is still the list the player grabbed. First the reads that
    -- resolved the owner are repeated: while their bytes are unchanged the
    -- resolution would find this owner again, and only a change resolves it
    -- afresh. Then the list's model is read again and must still be the
    -- grabbed list's.
    local function current_native(gesture)
        local api, bridge = state.native_api, state.native
        if not module.native_unchanged(api, bridge and bridge.tape) then
            bridge = module.native_resolve(api, state.native_memory)
            if not bridge or bridge.key ~= gesture.key then return nil end
        end
        local spare = state.native_model == live_models[1] and live_models[2] or live_models[1]
        local model = module.native_state(bridge, spare)
        local original = gesture.model
        if not model or model.items ~= original.items or model.kind ~= original.kind
            or math.abs(model.content - original.content) > 0.1
            or math.abs(model.span - original.span) > 0.1 then return nil end
        state.native, state.native_model = bridge, model
        return model
    end

    -- Moves the list to value. False when the write was refused: the route is
    -- retired and the gesture dropped.
    local function write_native(model, value)
        local written, reason = module.native_apply(state.native, model, value)
        if not written then
            native_retire(reason or 'write refused')
            drag, thumb, state.drag_active = nil, nil, false
            return false
        end
        if not drag.sent then state.drags = state.drags + 1 end
        state.drag_active = true
        state.native_writes = (state.native_writes or 0) + 1
        drag.sent, drag.writes = written, drag.writes + 1
        state.native_value = written
        return true
    end

    -- Verification also runs when the pointer stops. Small scrolls may leave
    -- the visible row indices unchanged: verify the rendered thumb in that
    -- case, instead of switching actuators halfway through a valid drag.
    -- Native geometry includes the rendered thumb: a rejected write never
    -- invokes screen capture to verify the same gesture.
    local function verify_native(now)
        if not drag.sent or drag.checked or now - drag.started < state.settings.native_verify_ms then return end
        local after = module.native_state(state.native)
        local moved = after and module.native_moved(drag.model, after)
        if not moved and math.abs(drag.sent - drag.model.value) * drag.track.span < 3 then return end
        drag.checked = true
        if moved then
            state.native_ok = (state.native_ok or 0) + 1
            note('native_drag')
        else
            native_retire('the game did not answer the write')
            drag, thumb, state.drag_active = nil, nil, false
        end
    end

    local function service_native_drag(now, cursor_y)
        local model = current_native(drag)
        if not model then
            drag, thumb, state.drag_active = nil, nil, false
            note('native_cancelled')
            return
        end
        -- The press snapshot is immutable for the entire gesture. Read-back
        -- refreshes the live model, never the origin of the pointer delta.
        local value = module.native_value_at_grab(drag.model, drag.track, drag.press_y, cursor_y)
        if not value then return end
        if math.abs(value - (drag.sent or drag.model.value)) > 0.000001 and not write_native(model, value) then
            return
        end
        verify_native(now)
    end

    -- A press on the bar arms the native gesture: the list's value follows the
    -- pointer for as long as the button is held, with no capture and no input.
    -- Failure cancels this hold instead of switching input routes mid-gesture.
    local function begin_native_drag(cursor_x, cursor_y, now, thumb_centre, thumb_height, left, right, side, native_track) -- lint-ok: R12 moved unchanged from the single file; existing debt, not new
        local model = state.native_model
        if not model or not thumb_centre or not thumb_height then return false end
        local track = native_track or module.native_track(model, thumb_centre - thumb_height / 2, thumb_height)
        if not track then return false end
        if state.native.route == 'settings' then
            if not module.native_settings_input(state.native) then
                note('settings_input_unavailable')
                return false
            end
            settings_capture = state.native
        end
        begin_drag(cursor_x, cursor_y, now, left, right, side, nil, track)
        drag.native, drag.track, drag.press_y = true, track, cursor_y
        drag.model, drag.key = model, state.native.key
        drag.started, drag.writes, drag.checked = now, 0, false
        record('native press y=%d track=%.1f..%.1f thumb=%.1f value=%.4f', cursor_y, track.top,
               track.top + track.length, track.thumb, model.value)
        return true
    end

    -- The grid is registered only while its Armory or loadout screen exists,
    -- and its controller is rebuilt with the screen, so resolution is attempted when
    -- it is needed, cached, and dropped the moment a read stops passing its
    -- bounds. A stale pointer therefore costs one failed read, never a write.
    local function refresh_native(now)
        -- Measurement is kept even after a write was refused: the grid's own
        -- geometry (content, span, value) locates the track independently of
        -- whether a later write is honoured.
        if not state.native_api then
            if state.native_api_attempted then return nil end
            state.native_api_attempted = true
            local ok, api, reason = pcall(module.native_api)
            if not ok or type(api) ~= 'table' then
                state.native_reason = tostring(reason or api)
                return nil
            end
            state.native_api = api
        end
        -- Each screen rebuilds its controller - and with it the grid - every time
        -- it is entered, so the grid is resolved from dispatch afresh
        -- on each press. A remembered pointer reads plausibly long after its screen
        -- is gone and writes into nothing, which is exactly the failure this
        -- replaces.
        -- One memory view serves every resolution of the session.
        state.native_memory = state.native_memory or module.native_memory(state.native_api)
        local bridge, reason = module.native_resolve(state.native_api, state.native_memory)
        state.native_reason = reason
        if not bridge then
            state.native, state.native_model = nil, nil
            return nil
        end
        if state.native_failed_key and state.native_failed_key ~= bridge.key then
            -- A different screen: an earlier refusal belongs to that one.
            state.native_failed, state.native_failures = nil, 0
        end
        local model, state_reason = module.native_state(bridge)
        state.native_state_reason = state_reason
        state.native = bridge
        if not model then
            state.native_model = nil
            return nil
        end
        state.native_model = model
        return state.native
    end

    local function handle_press(now)
        state.clicks = state.clicks + 1
        -- frame() asked for the focus before calling this.
        if not state.settings.enabled or state.settings.native ~= 1 then return end
        -- An absent/unsupported/hidden owner is a definitive no-op. Never scan
        -- gameplay pixels looking for a possible scrollbar on an ordinary click.
        local native = refresh_native(now)
        if not native then return end
        local native_track = platform.viewport
            and module.native_screen_track(state.native_model, platform.viewport())
        if not native_track then return end
        local cursor_x, cursor_y = platform.cursor()
        if not cursor_x then return end
        if cursor_x < native_track.left - 3 or cursor_x > native_track.right + 3
            or cursor_y < native_track.top or cursor_y > native_track.top + native_track.length then
            return
        end
        if state.native_failed then return end
        local model = state.native_model
        local top = native_track.top + model.value * native_track.span
        local centre = top + native_track.thumb / 2
        if not begin_native_drag(cursor_x, cursor_y, now, centre, native_track.thumb,
                                 native_track.left, native_track.right, nil, native_track) then return end
        if cursor_y < top or cursor_y > top + native_track.thumb then
            drag.press_y = centre
            service_native_drag(now, cursor_y)
            state.pages = state.pages + 1
            note('native_jump')
        else
            note('bar_press')
        end
    end

    -- --------------------------------------------------------- frame steps
    -- frame() runs once per game update and calls the steps below. They share
    -- the gesture through install's locals (drag, settings_capture) and `state`,
    -- and create no table or closure per frame.

    -- The engine refreshes selection state each frame. Consume it before
    -- native row/tab handlers run, even if scrolling was cancelled. Resolve
    -- only the input singleton here; a previous menu owner may be gone.
    local function hold_settings_input(down)
        if platform.foreground_self() and not module.native_settings_input(settings_capture) then
            drag, state.drag_active = nil, false
            note('settings_input_cancelled')
        end
        if not down then settings_capture = nil end
    end

    -- record formats the value itself, and only while diagnostics keep the trace,
    -- so a release allocates nothing (it formatted a string on every release).
    local function release_drag()
        if drag.native then
            note('native_release')
            if drag.sent then
                record('native release writes=%d value=%.4f', drag.writes or 0, drag.sent)
            else
                record('native release writes=%d value=none', drag.writes or 0)
            end
        end
        drag, state.drag_active = nil, false
    end

    -- The held gesture, then a new press. While the button is held the list's own
    -- scroll value follows the pointer (service_native_drag). started is the
    -- frame's clock when diagnostics read it, else false.
    local function track_gesture(started, down, pressed)
        -- Focus loss cancels ownership; resuming an old drag after alt-tab can
        -- use a different menu or deliver queued input to another application.
        -- A press is refused here too, before handle_press counts it.
        if not platform.foreground_self() then
            drag, state.drag_active = nil, false
            return
        end
        -- Only a held button moves the drag or presses; a release needs no clock.
        local now = down and (started or platform.now())
        if drag then
            if not down then
                release_drag()
            elseif drag.native then
                local cursor_x, cursor_y = platform.cursor()
                if state.native_failed then
                    -- The game did not answer: drop the gesture; a later press on
                    -- another controller may try again.
                    drag, state.drag_active = nil, false
                    note('native_dropped')
                elseif cursor_x then
                    service_native_drag(now, cursor_y)
                end
            end
        end
        if pressed then
            state.frame_clicks = state.frame_clicks + 1
            handle_press(now)
        end
    end

    -- The game's own frame interval, reported in the log with the capture budget
    -- sized from it: a machine already struggling to hold frames gets a smaller share.
    -- GetTickCount64 advances in steps of about 15.6 ms, so above ~64 FPS several
    -- frames share one value: the interval is a clock step over the frames it held.
    local frames_in_tick = 0
    local function measure_interval(now)
        frames_in_tick = frames_in_tick + 1
        if now == last_frame_ms then return end
        if last_frame_ms > 0 then
            local interval = clamp((now - last_frame_ms) / frames_in_tick, 1, 1000)
            state.frame_interval_ms = state.frame_interval_ms and (state.frame_interval_ms * 0.9 + interval * 0.1)
                or interval
            refresh_budget()
        end
        last_frame_ms, frames_in_tick = now, 0
    end

    -- The log's frame time, with diagnostics only.
    local function measure_frame_time(started)
        local elapsed = platform.now() - started
        state.frame_ms_total = state.frame_ms_total + elapsed
        if elapsed > state.frame_ms_max then state.frame_ms_max = elapsed end
    end

    -- Runs once per game update (the guard's step; render never calls it). Every
    -- update is a frame: v2.1 also ran it from render and skipped a frame whose
    -- clock equalled the last one, which above ~64 FPS dropped whole updates.
    local function frame()
        -- The clock serves only the log's frame interval and frame time, so it is
        -- read on an idle frame only while diagnostics are on.
        local diagnostics = state.settings.diagnostics == 1
        local started = diagnostics and platform.now()
        if started then measure_interval(started) end
        state.frames = state.frames + 1
        state.last_key = diagnostics and platform.key_state and platform.key_state() or 0
        local down = platform.pressed()
        local was_down, pressed = last_button, false
        if down then
            state.down_frames = state.down_frames + 1
            pressed = not was_down
        end
        last_button = down
        if settings_capture then hold_settings_input(down) end
        if not state.settings.enabled then
            drag, state.drag_active = nil, false
        -- The gesture step runs only with a gesture or a press: on any other frame
        -- none of its branches applies, so the focus is not asked either.
        elseif drag or pressed then
            track_gesture(started, down, pressed)
        end
        if started then measure_frame_time(started) end
        log(false)
    end

    -- The JIT never compiles frame(): every trace through it aborts in log(), which
    -- creates a closure (this LuaJIT compiles neither FNEW nor UCLO). Its steps stay
    -- in the interpreter with it, so they add no trace to the shared code cache;
    -- so do the press and held-drag steps, like the native layer they drive.
    keep_interpreted({frame, hold_settings_input, track_gesture, release_drag, handle_press, refresh_native,
                      begin_native_drag, begin_drag, service_native_drag, current_native, write_native,
                      verify_native, native_retire, measure_interval, measure_frame_time})

    -- The update chain is runtime.guard's (Bingus Shared Runtime): error_limit
    -- own errors in a burst (ERROR_BURST_FRAMES clean frames end it) or as many
    -- failed updates below stop the addon; an update below that raised pauses it
    -- (the gesture and the settings capture are dropped) until 60 clean frames.
    -- A failing frame drops its half-finished interaction and is counted in
    -- state; the log is written at a burst's first error and when the addon
    -- stops; the stop reason survives shutdown.
    local frame_error, clean_frames = false, 0
    local guard

    local function step()
        frame_error = false
        local ok, reason = pcall(frame)
        if ok then return end
        frame_error = true
        local text = tostring(reason)
        state.errors = state.errors + 1
        state.last_error = text
        drag, state.drag_active = nil, false
        note('frame_error')
        record('error update #%d: %s', state.errors, text)
        error(text, 0)
    end

    -- After the update below: the burst count the log reports.
    local function after()
        if frame_error then clean_frames = 0 else clean_frames = clean_frames + 1 end
        state.burst_errors = clean_frames >= ERROR_BURST_FRAMES and 0 or guard.status.errors
    end

    local function pause()
        drag, state.drag_active, settings_capture = nil, false, nil
    end

    local function stop(reason)
        settings_capture = nil
        if reason == 'shutdown' then
            state.status = 'stopped'
            record('shutdown frames=%d clicks=%d pages=%d', state.frames or 0, state.clicks or 0, state.pages or 0)
            log(true)
            pcall(platform.close)
            return
        end
        state.status = reason
        log(true)
    end

    guard = runtime.guard({name = 'ClickableScrollbars', step = step, after = after, stop = stop, pause = pause,
                           errors = state.settings.error_limit, clean = ERROR_BURST_FRAMES, env = environment,
                           log = function(line)
                               record('%s', line)
                               if line:find(' error: ', 1, true) then log(true) end
                           end}).install()
    state.guard = guard.status

    -- Only update owns input processing. Running it again from render can
    -- double the native reads and log work within a single displayed frame.
    refresh_geometry(true)
    state.status = state.settings.enabled and 'running' or 'disabled: config'
    log(true)
    return state
end
end
-- Click-to-scroll: the visible menu's own scroll model follows the pointer.
-- Unsupported or hidden menus are inert; gestures never capture or inject input.
-- Loader-only: plaintext Lua, no DLL, no hook, no code patch. See docs/RESEARCH.md.

-- A second copy of the addon loads nothing: the first one runs.
if rawget(_G, 'ClickableScrollbars') then return end

local module = {revision = 'v2.15.1'}

-- Keeps these functions, and the functions defined inside them, in the
-- interpreter; without the jit library it does nothing. A function that gets
-- hot on its own becomes a trace root in the machine-code cache the game and
-- every mod share. The native layer (native, memory, locate and model) runs
-- only on presses and while a scrollbar is held. In v2.14 its traces aborted
-- on the closures each call created; closure-free, it would now add about
-- 70 KB of machine code to the shared cache for frames that only occur during
-- a drag. Each of its files keeps its functions in the interpreter, with the
-- closures of the reader, the memory view and the game routine wrappers.
local function keep_interpreted(functions)
    local jit_library = rawget(_G, 'jit')
    if jit_library and jit_library.off then
        for _, fn in ipairs(functions) do jit_library.off(fn, true) end
    end
end

local function clamp(value, low, high)
    if value < low then return low end
    if value > high then return high end
    return value
end

-- Source files: cs_files.<name> = src/<name>.lua as a function, each run once
-- below, in this order. The build places them ahead of this file as the local
-- cs_files; the tests load that built entry. cs: what the files share. Each
-- file takes what it uses as locals, so every call and constant costs what it
-- did when the addon was one file, and adds to module and cs what later files
-- use. src/detector.lua, the legacy pixel detector, is not shipped: only the
-- offline tests load it.
local cs = {keep_interpreted = keep_interpreted, clamp = clamp}
cs.runtime = cs_files.bingus_runtime(module, cs) -- Bingus Shared Runtime: the update guard (vendored)
cs.bingus_memory = cs_files.bingus_memory(module, cs) -- its read side: the game build check (vendored)
cs_files.native(module, cs)   -- the UI bridge, the game's scroll routines and the native writes
cs_files.memory(module, cs)   -- memory views and the reader the addon ships with
cs_files.locate(module, cs)   -- resolving the visible scrollbar's owner
cs_files.model(module, cs)    -- the owner's scroll model, read in blocks
cs_files.settings(module, cs) -- defaults, the optional ini and the display scale
cs_files.platform(module, cs) -- the Windows functions the runtime calls
cs_files.install(module, cs)  -- the runtime: presses, held drags, the log and the error policy

if rawget(_G, '__CLICKABLE_SCROLLBARS_TEST') then
    return module
end

local ok, reason = module.install(module.create_platform)
if not ok then
    local loader = rawget(_G, 'CowboyBingusModLoader')
    print('[ClickableScrollbars] ' .. tostring(reason))
    pcall(function()
        local file = loader and loader.open_log and loader.open_log('ClickableScrollbars.log')
        if file then
            file:write(module.revision .. '\nstatus=' .. tostring(reason) .. '\n')
            file:close()
        end
    end)
end
